TEMPFILE_VERSION = "3.23.0"
TEMPFILE_CHECKSUM = "2d31c77bdf42a745371d260a26ca7163f1e0924b64afa0b688e61b5a9fa02f16"

# Filled exactly once after the external implementation preflight has frozen
# every host path, endpoint, semantic table, and later-bound digest.  The
# controller SHA itself is deliberately represented by the literal "self" in
# this stream to avoid a circular hash dependency.  A zero value is terminal
# and keeps this moving implementation checkpoint non-runnable.
PREFLIGHT_AUTHORITY_SHA256 = "0" * 64

POLICY_PHASES = tuple(
    phase
    for phase in PHASES
    if phase
    not in (
        "acquisition-setup",
        "graph-finalize",
        "source-audit",
        "pre-runtime-finalize",
    )
)


class ControllerError(RuntimeError):
    """A terminal, non-retryable violation of the frozen contract."""


def fail(message: str) -> None:
    raise ControllerError(message)


def checked_add(left: int, right: int, limit: int = U64_MAX) -> int:
    if left < 0 or right < 0 or left > limit - right:
        fail("checked integer overflow")
    return left + right


def raw_key(value: str) -> bytes:
    try:
        encoded = value.encode("utf-8", "strict")
    except UnicodeError as exc:
        raise ControllerError("non-UTF-8 path or label") from exc
    if any(byte < 0x20 or byte == 0x7F for byte in encoded):
        fail("control byte in path or label")
    return encoded


def require_sha256(value: str) -> str:
    if re.fullmatch(r"[0-9a-f]{64}", value) is None:
        fail("invalid SHA-256 encoding")
    return value


def require_uint(value: str) -> int:
    if re.fullmatch(r"0|[1-9][0-9]*", value) is None:
        fail("invalid unsigned integer")
    parsed = int(value, 10)
    if parsed > U64_MAX:
        fail("unsigned integer exceeds u64")
    return parsed


def canonical_absolute_lexical(path: str) -> str:
    raw_key(path)
    if not path.startswith("/") or "//" in path or path.endswith("/"):
        fail("path is not canonical absolute")
    components = path.split("/")[1:]
    if not components or any(part in ("", ".", "..") for part in components):
        fail("path contains a forbidden component")
    return path


def canonical_absolute(path: str, *, must_exist: bool) -> str:
    canonical_absolute_lexical(path)
    if must_exist:
        if os.path.realpath(path) != path:
            fail("existing path is not canonical or traverses a symlink")
    else:
        parent = os.path.dirname(path)
        if os.path.realpath(parent) != parent:
            fail("new path parent is not canonical")
    return path


def _open_directory_nofollow(path: str) -> int:
    """Open an existing absolute directory by walking every component no-follow."""
    if path != "/":
        canonical_absolute(path, must_exist=True)
    flags = (
        os.O_RDONLY
        | os.O_DIRECTORY
        | os.O_CLOEXEC
        | getattr(os, "O_NOFOLLOW", 0)
    )
    current = os.open("/", flags)
    try:
        for component in path.split("/")[1:]:
            following = os.open(component, flags, dir_fd=current)
            os.close(current)
            current = following
        return current
    except BaseException:
        os.close(current)
        raise


def validate_fresh_root(kind: str, path: str, *, must_exist: bool) -> str:
    canonical_absolute(path, must_exist=must_exist)
    return validate_fresh_root_lexical(kind, path)


def validate_fresh_root_lexical(kind: str, path: str) -> str:
    canonical_absolute_lexical(path)
    if ROOT_RE[kind].fullmatch(path) is None:
        fail("fresh root does not match the frozen grammar")
    if any(ch.isspace() or ch in ":=" for ch in path):
        fail("fresh root contains forbidden syntax")
    return path


def _open_absolute(
    path: str,
    flags: int,
    mode: int = 0o600,
    *,
    xattr_capability: XattrObjectCapability | None = None,
    parent_xattr_capability: XattrObjectCapability | None = None,
) -> int:
    creating = bool(flags & os.O_CREAT)
    canonical_absolute(path, must_exist=not creating)
    if creating != (
        xattr_capability is not None and parent_xattr_capability is not None
    ):
        fail("create-new absolute open lacks its child and parent capabilities")
    if not creating and (
        xattr_capability is not None or parent_xattr_capability is not None
    ):
        fail("non-creating absolute open received a creation capability")
    if xattr_capability is not None and xattr_capability.path != path:
        fail("create-new absolute open received a capability for another path")
    if xattr_capability is not None:
        selected_profile = _xattr_profile_from_capability(
            CURRENT_AUTHORITY,
            xattr_capability.traversal,
            path,
            root=xattr_capability.is_root,
        )
        if selected_profile != xattr_capability.profile:
            fail("create-new absolute open received a changed capability")
    parent, name = os.path.split(path)
    if (
        parent_xattr_capability is not None
        and parent_xattr_capability.path != parent
    ):
        fail("create-new absolute open received a capability for another parent")
    if parent_xattr_capability is not None:
        selected_parent_profile = _xattr_profile_from_capability(
            CURRENT_AUTHORITY,
            parent_xattr_capability.traversal,
            parent,
            root=parent_xattr_capability.is_root,
        )
        if selected_parent_profile != parent_xattr_capability.profile:
            fail("create-new absolute open received a changed parent capability")
    parent_fd = _open_directory_nofollow(parent)
    fd: int | None = None
    try:
        if creating:
            assert parent_xattr_capability is not None
            parent_before = _validate_xattr_object_fd(
                parent_fd,
                CURRENT_AUTHORITY,
                parent_xattr_capability,
                expected_uid=os.getuid(),
                expected_gid=os.getgid(),
            )
            names_before = sorted(os.listdir(parent_fd), key=raw_key)
            if name in names_before or len(names_before) != len(set(names_before)):
                fail("create-new absolute parent is noncanonical or already contains child")
        fd = os.open(
            name,
            flags | os.O_CLOEXEC | getattr(os, "O_NOFOLLOW", 0),
            mode,
            dir_fd=parent_fd,
        )
        if creating:
            assert xattr_capability is not None
            _normalize_created_fd(fd, CURRENT_AUTHORITY, xattr_capability)
            assert parent_xattr_capability is not None
            parent_after = _validate_xattr_object_fd(
                parent_fd,
                CURRENT_AUTHORITY,
                parent_xattr_capability,
                expected_uid=os.getuid(),
                expected_gid=os.getgid(),
            )
            names_after = sorted(os.listdir(parent_fd), key=raw_key)
            if (
                not _directory_container_identity_equal(parent_before, parent_after)
                or names_after != sorted((*names_before, name), key=raw_key)
            ):
                fail("create-new absolute parent changed outside its selected entry")
        return fd
    except BaseException:
        if fd is not None:
            os.close(fd)
        raise
    finally:
        os.close(parent_fd)


def _same_identity(left: os.stat_result, right: os.stat_result) -> bool:
    return (
        left.st_dev == right.st_dev
        and left.st_ino == right.st_ino
        and stat.S_IFMT(left.st_mode) == stat.S_IFMT(right.st_mode)
    )


def _full_identity_equal(left: os.stat_result, right: os.stat_result) -> bool:
    return (
        left.st_dev,
        left.st_ino,
        left.st_mode,
        left.st_nlink,
        left.st_uid,
        left.st_gid,
        left.st_size,
        left.st_mtime_ns,
        left.st_ctime_ns,
    ) == (
        right.st_dev,
        right.st_ino,
        right.st_mode,
        right.st_nlink,
        right.st_uid,
        right.st_gid,
        right.st_size,
        right.st_mtime_ns,
        right.st_ctime_ns,
    )


def _birthtime_ns(info: os.stat_result) -> int:
    if hasattr(info, "st_birthtime_ns"):
        value = info.st_birthtime_ns
    elif hasattr(info, "st_birthtime"):
        value = int(info.st_birthtime * 1_000_000_000)
    else:
        fail("Darwin stat result lacks birthtime")
    if (
        not isinstance(value, int)
        or isinstance(value, bool)
        or not 0 <= value <= U64_MAX
    ):
        fail("Darwin birthtime nanoseconds are outside the unsigned bound")
    return value


def _full_darwin_identity_equal(
    left: os.stat_result, right: os.stat_result
) -> bool:
    return (
        hasattr(left, "st_flags")
        and hasattr(right, "st_flags")
        and _full_identity_equal(left, right)
        and left.st_flags == right.st_flags
        and _birthtime_ns(left) == _birthtime_ns(right)
    )


def _private_tmp_parent_identity_equal(
    left: os.stat_result, right: os.stat_result
) -> bool:
    if not hasattr(left, "st_flags") or not hasattr(right, "st_flags"):
        return False
    return (
        left.st_dev,
        left.st_ino,
        stat.S_IFMT(left.st_mode),
        stat.S_IMODE(left.st_mode),
        left.st_uid,
        left.st_gid,
        left.st_flags,
    ) == (
        right.st_dev,
        right.st_ino,
        stat.S_IFMT(right.st_mode),
        stat.S_IMODE(right.st_mode),
        right.st_uid,
        right.st_gid,
        right.st_flags,
    )


def _directory_container_identity_equal(
    left: os.stat_result, right: os.stat_result
) -> bool:
    return (
        stat.S_ISDIR(left.st_mode)
        and stat.S_ISDIR(right.st_mode)
        and hasattr(left, "st_flags")
        and hasattr(right, "st_flags")
        and (
            left.st_dev,
            left.st_ino,
            stat.S_IMODE(left.st_mode),
            left.st_uid,
            left.st_gid,
            left.st_flags,
            _birthtime_ns(left),
        )
        == (
            right.st_dev,
            right.st_ino,
            stat.S_IMODE(right.st_mode),
            right.st_uid,
            right.st_gid,
            right.st_flags,
            _birthtime_ns(right),
        )
    )


def read_regular(path: str, *, maximum: int = U64_MAX) -> bytes:
    fd = _open_absolute(path, os.O_RDONLY)
    try:
        return _read_regular_fd(fd, maximum=maximum)
    finally:
        os.close(fd)


def _read_regular_fd(fd: int, *, maximum: int) -> bytes:
    before = os.fstat(fd)
    if not stat.S_ISREG(before.st_mode) or before.st_nlink != 1:
        fail("input is not a single-link regular file")
    if before.st_size < 0 or before.st_size > maximum:
        fail("input exceeds its byte ceiling")
    os.lseek(fd, 0, os.SEEK_SET)
    chunks: list[bytes] = []
    total = 0
    while True:
        chunk = os.read(fd, min(1 << 20, maximum - total + 1))
        if not chunk:
            break
        total = checked_add(total, len(chunk), maximum)
        chunks.append(chunk)
    after = os.fstat(fd)
    if not _same_identity(before, after) or (
        before.st_mode,
        before.st_nlink,
        before.st_size,
        before.st_mtime_ns,
        before.st_ctime_ns,
    ) != (
        after.st_mode,
        after.st_nlink,
        after.st_size,
        after.st_mtime_ns,
        after.st_ctime_ns,
    ):
        fail("input changed while read")
    data = b"".join(chunks)
    if len(data) != before.st_size:
        fail("input length changed while read")
    return data


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: str, *, maximum: int = U64_MAX) -> str:
    return sha256_bytes(read_regular(path, maximum=maximum))


def verify_file(path: str, expected_sha256: str, *, maximum: int = U64_MAX) -> None:
    if sha256_file(path, maximum=maximum) != require_sha256(expected_sha256):
        fail("file identity mismatch")


def _json_string(value: str) -> bytes:
    try:
        value.encode("utf-8", "strict")
    except UnicodeError as exc:
        raise ControllerError("non-UTF-8 JSON string") from exc
    output = bytearray(b'"')
    for char in value:
        code = ord(char)
        if char == '"':
            output.extend(b'\\"')
        elif char == "\\":
            output.extend(b"\\\\")
        elif code <= 0x1F:
            output.extend(("\\u%04x" % code).encode("ascii"))
        elif 0xD800 <= code <= 0xDFFF:
            fail("surrogate scalar in JSON string")
        else:
            output.extend(char.encode("utf-8"))
    output.extend(b'"')
    return bytes(output)


def canonical_json(value: Any) -> bytes:
    if value is True:
        return b"true"
    if value is False:
        return b"false"
    if isinstance(value, int) and not isinstance(value, bool):
        if value < 0 or value > U64_MAX:
            fail("JSON integer is outside u64")
        return str(value).encode("ascii")
    if isinstance(value, str):
        return _json_string(value)
    if isinstance(value, list) or isinstance(value, tuple):
        return b"[" + b",".join(canonical_json(item) for item in value) + b"]"
    if isinstance(value, dict):
        encoded: list[bytes] = []
        for key, item in value.items():
            if not isinstance(key, str):
                fail("JSON object key is not a string")
            encoded.append(_json_string(key) + b":" + canonical_json(item))
        return b"{" + b",".join(encoded) + b"}"
    fail("forbidden JSON value type")
    raise AssertionError("unreachable")


def canonical_json_line(value: Any) -> bytes:
    return canonical_json(value) + b"\n"


def _bounded_canonical_json_size(value: Any, maximum: int) -> int:
    if type(maximum) is not int or maximum < 0 or maximum > U64_MAX:
        fail("canonical JSON byte ceiling is outside u64")
    total = 0
    pending: list[tuple[str, Any]] = [("value", value)]
    while pending:
        operation, item = pending.pop()
        if operation == "sequence":
            try:
                child = next(item)
            except StopIteration:
                continue
            pending.append(("sequence", item))
            pending.append(("value", child))
            continue
        if operation == "mapping":
            try:
                key, child = next(item)
            except StopIteration:
                continue
            if not isinstance(key, str):
                fail("JSON object key is not a string")
            pending.append(("mapping", item))
            pending.append(("value", child))
            pending.append(("value", key))
            continue
        if operation != "value":
            fail("canonical JSON sizing operation is invalid")
        if item is True:
            encoded_size = 4
        elif item is False:
            encoded_size = 5
        elif isinstance(item, int) and not isinstance(item, bool):
            if item < 0 or item > U64_MAX:
                fail("JSON integer is outside u64")
            encoded_size = len(str(item))
        elif isinstance(item, str):
            encoded_size = 2
            for character in item:
                code = ord(character)
                if character in ('"', "\\"):
                    character_size = 2
                elif code <= 0x1F:
                    character_size = 6
                elif 0xD800 <= code <= 0xDFFF:
                    fail("surrogate scalar in JSON string")
                else:
                    character_size = len(character.encode("utf-8"))
                encoded_size = checked_add(
                    encoded_size, character_size, maximum
                )
        elif isinstance(item, (list, tuple)):
            encoded_size = checked_add(
                2, max(0, len(item) - 1), maximum
            )
            pending.append(("sequence", iter(item)))
        elif isinstance(item, dict):
            encoded_size = checked_add(
                2, max(0, len(item) - 1), maximum
            )
            encoded_size = checked_add(encoded_size, len(item), maximum)
            pending.append(("mapping", iter(item.items())))
        else:
            fail("forbidden JSON value type")
        total = checked_add(total, encoded_size, maximum)
    return total


def decode_canonical_json_line(data: bytes) -> Any:
    if not data.endswith(b"\n") or data.endswith(b"\n\n"):
        fail("JSON evidence does not have exactly one final LF")
    try:
        decoded = data[:-1].decode("utf-8", "strict")
        value = json.loads(
            decoded,
            parse_int=lambda text: require_uint(text),
            parse_float=lambda _text: fail("float in canonical JSON"),
            object_pairs_hook=_unique_object,
        )
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ControllerError("invalid canonical JSON") from exc
    if canonical_json_line(value) != data:
        fail("JSON bytes are not canonical")
    return value


def _unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            fail("duplicate JSON object key")
        result[key] = value
    return result


def _write_all(fd: int, data: bytes) -> None:
    offset = 0
    while offset < len(data):
        written = os.write(fd, data[offset:])
        if written <= 0:
            fail("short evidence write")
        offset += written


def create_regular_at(
    authority: Authority,
    directory_fd: int,
    parent_path: str,
    name: str,
    data: bytes,
    *,
    xattr_capability: XattrTraversalCapability,
    mode: int = 0o600,
) -> tuple[int, str]:
    if "/" in name or name in ("", ".", ".."):
        fail("invalid create-new basename")
    path = parent_path + "/" + name
    parent_xattr_capability = _xattr_object_capability(
        authority,
        xattr_capability,
        parent_path,
        root=parent_path == xattr_capability.root,
    )
    object_xattr_capability = _xattr_object_capability(
        authority, xattr_capability, path, root=False
    )
    held_parent_before = _assert_generated_fd(
        directory_fd, authority, parent_xattr_capability
    )
    linked_parent_fd = _open_directory_nofollow(parent_path)
    try:
        linked_parent = _assert_generated_fd(
            linked_parent_fd, authority, parent_xattr_capability
        )
        if not _full_darwin_identity_equal(held_parent_before, linked_parent):
            fail("create-new parent path does not resolve to its held descriptor")
    finally:
        os.close(linked_parent_fd)
    fd = os.open(
        name,
        os.O_WRONLY
        | os.O_CREAT
        | os.O_EXCL
        | os.O_CLOEXEC
        | getattr(os, "O_NOFOLLOW", 0),
        mode,
        dir_fd=directory_fd,
    )
    try:
        _normalize_created_fd(
            fd, authority, object_xattr_capability
        )
        _write_all(fd, data)
        os.fsync(fd)
        created = os.fstat(fd)
        if not stat.S_ISREG(created.st_mode) or created.st_nlink != 1:
            fail("created evidence is not a single-link regular file")
        if stat.S_IMODE(created.st_mode) != mode:
            fail("created evidence has the wrong mode")
    finally:
        os.close(fd)
    reopened = os.open(
        name,
        os.O_RDONLY | os.O_CLOEXEC | getattr(os, "O_NOFOLLOW", 0),
        dir_fd=directory_fd,
    )
    try:
        current = _assert_generated_fd(
            reopened, authority, object_xattr_capability
        )
        if not _same_identity(created, current):
            fail("created evidence identity changed")
        digest = hashlib.sha256()
        size = 0
        while True:
            chunk = os.read(reopened, 1 << 20)
            if not chunk:
                break
            size = checked_add(size, len(chunk))
            digest.update(chunk)
        if size != len(data) or digest.hexdigest() != sha256_bytes(data):
            fail("created evidence bytes changed")
    finally:
        os.close(reopened)
    held_parent_after = _assert_generated_fd(
        directory_fd, authority, parent_xattr_capability
    )
    if not _directory_container_identity_equal(
        held_parent_before, held_parent_after
    ):
        fail("create-new changed its held parent outside the selected entry")
    return len(data), digest.hexdigest()


def _mode_text(mode: int) -> str:
    return f"{stat.S_IMODE(mode):04o}"


def _xattr_names_fd(fd: int) -> tuple[bytes, ...]:
    size = _LIBC.flistxattr(fd, None, 0, 0)
    if size < 0:
        fail("cannot size extended-attribute name list")
    if size == 0:
        return ()
    if size > 268_435_456:
        fail("extended-attribute name list exceeds its byte ceiling")
    buffer = ctypes.create_string_buffer(size)
    observed = _LIBC.flistxattr(fd, buffer, size, 0)
    if observed != size:
        fail("extended-attribute name list changed while read")
    raw = bytes(buffer.raw[:size])
    if not raw.endswith(b"\x00"):
        fail("extended-attribute name list is malformed")
    names = tuple(raw.split(b"\x00")[:-1])
    if (
        not all(name and len(name) <= 255 and b"\x00" not in name for name in names)
        or len(names) != len(set(names))
        or len(names) > 1_048_576
    ):
        fail("extended-attribute name table is invalid")
    return tuple(sorted(names))


def _xattr_value_fd(fd: int, name: bytes) -> bytes:
    size = _LIBC.fgetxattr(fd, name, None, 0, 0, 0)
    if size < 0 or size > 16_777_216:
        fail("cannot size extended attribute or value exceeds bound")
    if size == 0:
        return b""
    buffer = ctypes.create_string_buffer(size)
    observed = _LIBC.fgetxattr(fd, name, buffer, size, 0, 0)
    if observed != size:
        fail("extended attribute changed while read")
    return bytes(buffer.raw[:size])


def _xattr_snapshot_fd_once(fd: int) -> tuple[tuple[bytes, bytes], ...]:
    names_before = _xattr_names_fd(fd)
    result: list[tuple[bytes, bytes]] = []
    total = 0
    for name in names_before:
        value = _xattr_value_fd(fd, name)
        total = checked_add(total, len(value), 1_073_741_824)
        result.append((name, value))
    if _xattr_names_fd(fd) != names_before:
        fail("extended-attribute name table changed while read")
    return tuple(result)


def _xattrs_fd(
    fd: int, *, private_tmp_parent: bool = False
) -> tuple[tuple[bytes, bytes], ...]:
    before_identity = os.fstat(fd)
    first = _xattr_snapshot_fd_once(fd)
    middle_identity = os.fstat(fd)
    second = _xattr_snapshot_fd_once(fd)
    after_identity = os.fstat(fd)
    identity_equal = (
        _private_tmp_parent_identity_equal
        if private_tmp_parent
        else _full_identity_equal
    )
    if (
        not identity_equal(before_identity, middle_identity)
        or not identity_equal(middle_identity, after_identity)
        or first != second
    ):
        fail("extended-attribute snapshot or held object changed while read")
    return first


def c2b2a_validate_xattr_profile(actual, expected):
    if tuple(actual) != tuple(expected):
        raise ValueError("xattr-profile-mismatch")
    return tuple(actual)


def _validate_exact_xattr_profile(
    attrs: Sequence[tuple[bytes, bytes]], profile: str
) -> tuple[tuple[bytes, bytes], ...]:
    if profile not in XATTR_PROFILES:
        fail("unknown exact xattr profile")
    try:
        accepted_attrs = c2b2a_validate_xattr_profile(
            attrs, XATTR_PROFILES[profile]
        )
    except ValueError as exc:
        raise ControllerError("exact xattr profile mismatch") from exc
    return accepted_attrs


def _normalize_created_fd(
    fd: int,
    authority: Authority,
    xattr_capability: XattrObjectCapability,
) -> None:
    """Validate one newly created descendant; never synthesize host xattrs or ACLs."""
    if not isinstance(xattr_capability, XattrObjectCapability):
        fail("created object lacks its pre-open xattr capability")
    profile = _xattr_profile_from_capability(
        authority,
        xattr_capability.traversal,
        xattr_capability.path,
        root=xattr_capability.is_root,
    )
    if profile != xattr_capability.profile:
        fail("created object xattr capability changed after selection")
    before = os.fstat(fd)
    if before.st_uid != os.getuid():
        fail("controller-created object has an unexpected owner")
    accepted_attrs = _validate_exact_xattr_profile(_xattrs_fd(fd), profile)
    portable, native = _acl_external_fd(fd)
    _require_apfs_fd(fd)
    after = os.fstat(fd)
    if (
        not _full_identity_equal(before, after)
        or after.st_uid != os.getuid()
        or after.st_gid != os.getgid()
        or accepted_attrs != XATTR_PROFILES[profile]
        or portable
        or native
    ):
        fail("controller-created object metadata is not the exact descendant profile")


_LIBC = ctypes.CDLL(None, use_errno=True)
_LIBC.flistxattr.argtypes = (
    ctypes.c_int,
    ctypes.c_void_p,
    ctypes.c_size_t,
    ctypes.c_int,
)
_LIBC.flistxattr.restype = ctypes.c_ssize_t
_LIBC.fgetxattr.argtypes = (
    ctypes.c_int,
    ctypes.c_char_p,
    ctypes.c_void_p,
    ctypes.c_size_t,
    ctypes.c_uint32,
    ctypes.c_int,
)
_LIBC.fgetxattr.restype = ctypes.c_ssize_t
_LIBC.fstatfs.argtypes = (ctypes.c_int, ctypes.c_void_p)
_LIBC.fstatfs.restype = ctypes.c_int
_LIBC.acl_get_fd_np.argtypes = (ctypes.c_int, ctypes.c_int)
_LIBC.acl_get_fd_np.restype = ctypes.c_void_p
_LIBC.acl_init.argtypes = (ctypes.c_int,)
_LIBC.acl_init.restype = ctypes.c_void_p
_LIBC.acl_set_fd_np.argtypes = (ctypes.c_int, ctypes.c_void_p, ctypes.c_int)
_LIBC.acl_set_fd_np.restype = ctypes.c_int
_LIBC.acl_size.argtypes = (ctypes.c_void_p,)
_LIBC.acl_size.restype = ctypes.c_ssize_t
_LIBC.acl_copy_ext.argtypes = (ctypes.c_void_p, ctypes.c_void_p, ctypes.c_ssize_t)
_LIBC.acl_copy_ext.restype = ctypes.c_ssize_t
_LIBC.acl_copy_ext_native.argtypes = (
    ctypes.c_void_p,
    ctypes.c_void_p,
    ctypes.c_ssize_t,
)
_LIBC.acl_copy_ext_native.restype = ctypes.c_ssize_t
_LIBC.acl_get_entry.argtypes = (
    ctypes.c_void_p,
    ctypes.c_int,
    ctypes.POINTER(ctypes.c_void_p),
)
_LIBC.acl_get_entry.restype = ctypes.c_int
_LIBC.acl_free.argtypes = (ctypes.c_void_p,)
_LIBC.acl_free.restype = ctypes.c_int
_LIBC.proc_pidinfo.argtypes = (
    ctypes.c_int,
    ctypes.c_int,
    ctypes.c_uint64,
    ctypes.c_void_p,
    ctypes.c_int,
)
_LIBC.proc_pidinfo.restype = ctypes.c_int

PROC_PIDLISTFDS = 1
MAX_FD_ROWS = 1_048_576


class _ProcFdInfo(ctypes.Structure):
    _fields_ = (("fd", ctypes.c_int32), ("fd_type", ctypes.c_uint32))


class _DarwinStatfs(ctypes.Structure):
    _fields_ = (
        ("f_bsize", ctypes.c_uint32),
        ("f_iosize", ctypes.c_int32),
        ("f_blocks", ctypes.c_uint64),
        ("f_bfree", ctypes.c_uint64),
        ("f_bavail", ctypes.c_uint64),
        ("f_files", ctypes.c_uint64),
        ("f_ffree", ctypes.c_uint64),
        ("f_fsid", ctypes.c_int32 * 2),
        ("f_owner", ctypes.c_uint32),
        ("f_type", ctypes.c_uint32),
        ("f_flags", ctypes.c_uint32),
        ("f_fssubtype", ctypes.c_uint32),
        ("f_fstypename", ctypes.c_char * 16),
        ("f_mntonname", ctypes.c_char * 1024),
        ("f_mntfromname", ctypes.c_char * 1024),
        ("f_flags_ext", ctypes.c_uint32),
        ("f_reserved", ctypes.c_uint32 * 7),
    )


def _complete_fd_table() -> tuple[int, ...]:
    table_type = _ProcFdInfo * MAX_FD_ROWS
    table = table_type()
    capacity = ctypes.sizeof(table)
    returned = _LIBC.proc_pidinfo(
        os.getpid(), PROC_PIDLISTFDS, 0, ctypes.byref(table), capacity
    )
    if (
        returned <= 0
        or returned >= capacity
        or returned % ctypes.sizeof(_ProcFdInfo) != 0
    ):
        fail("proc_pidinfo descriptor enumeration is truncated or malformed")
    count = returned // ctypes.sizeof(_ProcFdInfo)
    descriptors = tuple(sorted(table[index].fd for index in range(count)))
    if any(fd < 0 for fd in descriptors) or len(descriptors) != len(set(descriptors)):
        fail("proc_pidinfo descriptor enumeration contains an invalid row")
    return descriptors


def _acl_external_fd(fd: int) -> tuple[bytes, bytes]:
    ctypes.set_errno(0)
    acl = _LIBC.acl_get_fd_np(fd, ACL_TYPE_EXTENDED)
    if not acl:
        number = ctypes.get_errno()
        if number in (0, errno.ENOENT):
            return b"", b""
        raise ControllerError("cannot read extended ACL") from OSError(
            number, os.strerror(number)
        )
    try:
        size = _LIBC.acl_size(acl)
        if size < 0 or size > 1_048_576:
            fail("extended ACL external representation exceeds its byte ceiling")
        if size == 0:
            return b"", b""
        portable_buffer = ctypes.create_string_buffer(size)
        native_buffer = ctypes.create_string_buffer(size)
        portable_size = _LIBC.acl_copy_ext(portable_buffer, acl, size)
        native_size = _LIBC.acl_copy_ext_native(native_buffer, acl, size)
        if portable_size != size or native_size != size:
            fail("extended ACL external representation is incomplete")
        portable = bytes(portable_buffer.raw[:size])
        native = bytes(native_buffer.raw[:size])
        if len(portable) != len(native):
            fail("extended ACL representations disagree on size")
        return portable, native
    finally:
        if _LIBC.acl_free(acl) != 0:
            fail("cannot free extended ACL")


def _clear_extended_acl_fd(fd: int) -> None:
    acl = _LIBC.acl_init(0)
    if not acl:
        number = ctypes.get_errno()
        raise ControllerError("cannot allocate empty extended ACL") from OSError(
            number, os.strerror(number)
        )
    try:
        if _LIBC.acl_set_fd_np(fd, acl, ACL_TYPE_EXTENDED) != 0:
            number = ctypes.get_errno()
            raise ControllerError("cannot apply empty extended ACL") from OSError(
                number, os.strerror(number)
            )
    finally:
        if _LIBC.acl_free(acl) != 0:
            fail("cannot free empty extended ACL")


def has_extended_acl(fd: int) -> bool:
    portable, native = _acl_external_fd(fd)
    if bool(portable) != bool(native):
        fail("extended ACL representations disagree on presence")
    return bool(portable)


def _c_string_field(value: Any) -> str:
    raw = bytes(value)
    prefix = raw.split(b"\x00", 1)[0]
    if not prefix or b"\x00" in prefix:
        fail("statfs string field is malformed")
    try:
        return prefix.decode("utf-8", "strict")
    except UnicodeError as exc:
        raise ControllerError("statfs string field is not UTF-8") from exc


def _fstatfs_projection(fd: int) -> tuple[Any, ...]:
    if ctypes.sizeof(_DarwinStatfs) != DARWIN_STATFS_SIZE or ctypes.alignment(
        _DarwinStatfs
    ) != 8:
        fail("selected Darwin statfs ABI size or alignment is wrong")
    expected_offsets = {
        "f_bsize": 0,
        "f_iosize": 4,
        "f_blocks": 8,
        "f_bfree": 16,
        "f_bavail": 24,
        "f_files": 32,
        "f_ffree": 40,
        "f_fsid": 48,
        "f_owner": 56,
        "f_type": 60,
        "f_flags": 64,
        "f_fssubtype": 68,
        "f_fstypename": 72,
        "f_mntonname": 88,
        "f_mntfromname": 1112,
        "f_flags_ext": 2136,
        "f_reserved": 2140,
    }
    if any(getattr(_DarwinStatfs, name).offset != offset for name, offset in expected_offsets.items()):
        fail("selected Darwin statfs ABI field offsets are wrong")
    value = _DarwinStatfs()
    if _LIBC.fstatfs(fd, ctypes.byref(value)) != 0:
        number = ctypes.get_errno()
        raise ControllerError("fstatfs failed") from OSError(number, os.strerror(number))
    return (
        tuple(int(item) for item in value.f_fsid),
        int(value.f_owner),
        int(value.f_type),
        int(value.f_flags),
        int(value.f_fssubtype),
        _c_string_field(value.f_fstypename),
        _c_string_field(value.f_mntonname),
        _c_string_field(value.f_mntfromname),
        int(value.f_flags_ext),
    )


EXPECTED_APFS_PROJECTION = (
    (16777233, 25),
    0,
    25,
    0x04909080,
    1,
    "apfs",
    "/System/Volumes/Data",
    "/dev/disk3s5",
    0x00000001,
)


def _require_apfs_fd(fd: int) -> tuple[Any, ...]:
    projection = _fstatfs_projection(fd)
    if projection != EXPECTED_APFS_PROJECTION or projection[3] & 0x00200000:
        fail("filesystem stable projection is not the accepted writable APFS volume")
    return projection


def assert_plain_fd(
    fd: int,
    *,
    expected_uid: int | None = None,
    expected_gid: int | None = None,
) -> os.stat_result:
    info = os.fstat(fd)
    if expected_uid is not None and info.st_uid != expected_uid:
        fail("filesystem object has the wrong owner")
    if expected_gid is not None and info.st_gid != expected_gid:
        fail("filesystem object has the wrong group")
    if has_extended_acl(fd):
        fail("unexpected extended ACL")
    return info


def _assert_generated_fd(
    fd: int,
    authority: Authority,
    xattr_capability: XattrObjectCapability,
    *,
    expected_uid: int | None = None,
    expected_gid: int | None = None,
) -> os.stat_result:
    if not isinstance(xattr_capability, XattrObjectCapability):
        fail("generated object lacks its pre-open xattr capability")
    profile = _xattr_profile_from_capability(
        authority,
        xattr_capability.traversal,
        xattr_capability.path,
        root=xattr_capability.is_root,
    )
    if profile != xattr_capability.profile:
        fail("generated object xattr capability changed after selection")
    info = assert_plain_fd(
        fd,
        expected_uid=os.getuid() if expected_uid is None else expected_uid,
        expected_gid=os.getgid() if expected_gid is None else expected_gid,
    )
    observed_attrs = _xattrs_fd(fd)
    accepted_attrs = _validate_exact_xattr_profile(observed_attrs, profile)
    if accepted_attrs != tuple(observed_attrs):
        fail("generated object xattr validator changed its accepted value")
    _require_apfs_fd(fd)
    return info


def _open_metadata_path(item: DarwinPathAuthority) -> int:
    if item.kind == "directory":
        return _open_directory_nofollow(item.path)
    if item.kind == "file":
        return _open_absolute(item.path, os.O_RDONLY)
    parent, name = os.path.split(item.path)
    parent_fd = _open_directory_nofollow(parent)
    try:
        return os.open(
            name,
            os.O_RDONLY | os.O_CLOEXEC | getattr(os, "O_NOFOLLOW", 0) | O_SYMLINK,
            dir_fd=parent_fd,
        )
    finally:
        os.close(parent_fd)


def _validate_bound_metadata_fd(fd: int, item: DarwinPathAuthority) -> os.stat_result:
    rule = _closed_darwin_path_rules().get(item.path)
    if rule is None or (
        item.kind,
        item.uid,
        item.gid,
        item.mode,
        item.xattr_profile,
        item.acl_portable,
        item.acl_native,
    ) != (
        rule.kind,
        rule.uid,
        rule.gid,
        rule.mode,
        rule.xattr_profile,
        rule.acl_portable,
        rule.acl_native,
    ):
        fail("preflight-bound Darwin path differs from its source-closed class")
    before = os.fstat(fd)
    if not hasattr(before, "st_flags"):
        fail("preflight-bound Darwin path lacks the required flags projection")
    expected_type = {
        "directory": stat.S_IFDIR,
        "file": stat.S_IFREG,
        "symlink": stat.S_IFLNK,
    }[item.kind]
    if (
        stat.S_IFMT(before.st_mode) != expected_type
        or before.st_dev != item.device
        or before.st_ino != item.inode
        or before.st_uid != item.uid
        or before.st_gid != item.gid
        or stat.S_IMODE(before.st_mode) != item.mode
        or before.st_flags != item.flags
    ):
        fail("preflight-bound Darwin path metadata changed")
    observed_attrs = _xattrs_fd(
        fd, private_tmp_parent=item.path == "/private/tmp"
    )
    accepted_attrs = _validate_exact_xattr_profile(
        observed_attrs, item.xattr_profile
    )
    if accepted_attrs != tuple(observed_attrs):
        fail("preflight-bound xattr validator changed its accepted value")
    portable, native = _acl_external_fd(fd)
    if portable != item.acl_portable or native != item.acl_native:
        fail("preflight-bound Darwin path ACL changed")
    _require_apfs_fd(fd)
    after = os.fstat(fd)
    if not hasattr(after, "st_flags"):
        fail("preflight-bound Darwin path lost the required flags projection")
    identity_equal = (
        _private_tmp_parent_identity_equal(before, after)
        if item.path == "/private/tmp"
        else _full_identity_equal(before, after)
    )
    if not identity_equal or after.st_flags != item.flags:
        fail("preflight-bound Darwin path changed during observation")
    return after


def _validate_xattr_object_fd(
    fd: int,
    authority: Authority,
    xattr_capability: XattrObjectCapability,
    *,
    expected_uid: int | None = None,
    expected_gid: int | None = None,
) -> os.stat_result:
    if not isinstance(xattr_capability, XattrObjectCapability):
        fail("metadata object lacks its pre-open capability")
    traversal = xattr_capability.traversal
    selected_profile = _xattr_profile_from_capability(
        authority,
        traversal,
        xattr_capability.path,
        root=xattr_capability.is_root,
    )
    if selected_profile != xattr_capability.profile:
        fail("metadata object capability changed after selection")
    item = authority.darwin_paths.get(xattr_capability.path)
    if item is not None:
        info = _validate_bound_metadata_fd(fd, item)
        if expected_uid is not None and info.st_uid != expected_uid:
            fail("preflight object has the wrong expected owner")
        if expected_gid is not None and info.st_gid != expected_gid:
            fail("preflight object has the wrong expected group")
        return info
    if traversal.object_class == "preflight-bound" and (
        xattr_capability.path not in traversal.generated_exceptions
    ):
        fail("preflight object lacks exact Darwin path authority")
    return _assert_generated_fd(
        fd,
        authority,
        xattr_capability,
        expected_uid=expected_uid,
        expected_gid=expected_gid,
    )


def _validate_darwin_path(authority: Authority, path: str) -> os.stat_result:
    item = authority.darwin_paths.get(path)
    if item is None:
        fail("path is absent from the complete Darwin metadata authority")
    fd = _open_metadata_path(item)
    try:
        return _validate_bound_metadata_fd(fd, item)
    finally:
        os.close(fd)


def _validate_darwin_repository_authority(authority: Authority) -> None:
    for path in authority.darwin_paths:
        _validate_darwin_path(authority, path)


def verify_initial_process(mode: str) -> None:
    expected = dict(BOOTSTRAP_ENV)
    if mode == "policy-probe":
        expected = dict(FIXED_PHASE_ENV)
        home = os.environ.get("HOME")
        temporary = os.environ.get("TMPDIR")
        if home is None or temporary is None:
            fail("policy probe is missing HOME or TMPDIR")
        expected["HOME"] = home
        expected["TMPDIR"] = temporary
    if dict(os.environ) != expected:
        fail("initial environment is not exact")
    if os.getcwd() != EMPTY_CWD:
        fail("initial cwd is not /var/empty")
    previous = os.umask(0o077)
    os.umask(0o077)
    if previous != 0o077:
        fail("initial umask is not 0077")

    first_fd_table = _complete_fd_table()
    second_fd_table = _complete_fd_table()
    if first_fd_table != second_fd_table or first_fd_table != (0, 1, 2):
        fail("initial descriptor table is not exactly 0,1,2")

    null_info = os.stat(DEV_NULL, follow_symlinks=False)
    stdin_info = os.fstat(0)
    if not stat.S_ISCHR(stdin_info.st_mode) or not _same_identity(null_info, stdin_info):
        fail("fd 0 is not /dev/null")
    if (fcntl.fcntl(0, fcntl.F_GETFL) & os.O_ACCMODE) != os.O_RDONLY:
        fail("fd 0 is not read-only")
    outputs: list[os.stat_result] = []
    for fd in (1, 2):
        info = os.fstat(fd)
        if not stat.S_ISFIFO(info.st_mode):
            fail("diagnostic fd is not a pipe")
        if (fcntl.fcntl(fd, fcntl.F_GETFL) & os.O_ACCMODE) != os.O_WRONLY:
            fail("diagnostic fd is not write-only")
        try:
            os.lseek(fd, 0, os.SEEK_CUR)
        except OSError as exc:
            if exc.errno != errno.ESPIPE:
                fail("diagnostic fd failed nonseekable verification")
        else:
            fail("diagnostic fd is seekable")
        outputs.append(info)
    if _same_identity(outputs[0], outputs[1]):
        fail("stdout and stderr are not distinct pipes")


