def support_paths() -> Mapping[str, str]:
    return {
        "controller": CONTROLLER,
        "provisioner": PROVISIONER,
        "root-config": ROOT_CONFIG,
        "entropy-probe-cc": ENTROPY_PROBE_CC,
        "entropy-probe-rs": ENTROPY_PROBE_RS,
        "patch": PATCH,
    }


def verify_authority(authority: Authority) -> None:
    accepted_retained_state_table = _retained_state_table_stream(authority)
    if (
        accepted_retained_state_table.count(b"\n")
        != authority.retained_state_table_binding.rows
        or len(accepted_retained_state_table)
        != authority.retained_state_table_binding.bytes
        or sha256_bytes(accepted_retained_state_table)
        != authority.retained_state_table_binding.sha256
    ):
        fail("retained-state table changed during authority verification")
    if PREFLIGHT_AUTHORITY_SHA256 == "0" * 64:
        fail("implementation-preflight authority digest has not been frozen")
    if sha256_bytes(canonical_json_line(_authority_object(authority))) != (
        PREFLIGHT_AUTHORITY_SHA256
    ):
        fail("runtime authority differs from the embedded reviewed authority")
    for name, path in support_paths().items():
        verify_file(path, authority.support_sha256[name])
    if authority.support_sha256["patch"] != PATCH_SHA256:
        fail("patch authority does not match the accepted freeze")
    for tool in authority.tools.values():
        verify_file(tool.path, tool.sha256)
    for executable in authority.phase_executables:
        verify_file(executable.path, executable.sha256)
    for path, digest in PROTECTED_SHA256.items():
        verify_file(path, digest)
    _validate_darwin_repository_authority(authority)
    _validate_authority_topology(authority)
    tool_roots = tuple(item.path for item in authority.tool_roots)
    system_paths = {item.path for item in authority.system_inputs}
    for executable in authority.phase_executables:
        if not any(_path_is_beneath(executable.path, root) for root in tool_roots):
            fail("phase executable lies outside the sealed tool roots")
    for phase in POLICY_PHASES:
        for path in authority.phase_runtime_literals[phase]:
            if path not in system_paths and not any(
                _path_is_beneath(path, root) for root in tool_roots
            ):
                fail("phase runtime literal lies outside sealed tool/system authority")
        for path in authority.phase_runtime_subpaths[phase]:
            if not any(_path_is_beneath(path, root) for root in tool_roots):
                fail("phase runtime subpath lies outside a recursively sealed tool root")
    for item in authority.generated_exec_classes:
        owner = _phase_owner_root(authority, item.phase)
        required_prefix = owner + "/target/"
        if required_prefix not in item.expression:
            fail("generated executable class is not rooted in its exact target")
        try:
            re.compile(item.expression)
        except re.error as exc:
            raise ControllerError("generated executable class is invalid") from exc


