def _retained_state_table_rows(
    authority: Authority,
) -> tuple[tuple[Any, ...], ...]:
    acquisition = authority.acquisition_root
    lock_root = acquisition + "/lock-root"
    root_rows: tuple[tuple[Any, ...], ...] = ()
    for sequence, (root_class, suffix, scope) in enumerate(
        RETAINED_STATE_ACQUISITION_ROOT_SPECS
    ):
        root_rows += (("root", 0, sequence, root_class, acquisition + suffix, scope),)
    for edge_sequence in (1, 2):
        for sequence, (root_class, suffix, scope) in enumerate(
            RETAINED_STATE_LOCK_ROOT_SPECS
        ):
            path = (
                acquisition + suffix[len("@acquisition") :]
                if suffix.startswith("@acquisition")
                else lock_root + suffix
            )
            root_rows += (("root", edge_sequence, sequence, root_class, path, scope),)
    entry_rows: tuple[tuple[Any, ...], ...] = tuple(
        (
            "entry",
            0,
            0,
            sequence,
            "directory",
            name,
            disposition,
        )
        for sequence, (name, disposition) in enumerate(
            RETAINED_STATE_ACQUISITION_ENTRY_SPECS
        )
    )
    for edge_sequence in (1, 2):
        entry_rows += tuple(
            (
                "entry",
                edge_sequence,
                0,
                sequence,
                "directory",
                name,
                disposition,
            )
            for sequence, (name, disposition) in enumerate(
                RETAINED_STATE_LOCK_ENTRY_SPECS
            )
        )
    return (
        RETAINED_STATE_EDGE_ROWS,
        root_rows,
        entry_rows,
        RETAINED_STATE_ABSENCE_ROWS,
        RETAINED_STATE_OBSERVATION_ROWS,
    )


def _retained_state_table_stream(authority: Authority) -> bytes:
    edge_rows, root_rows, entry_rows, absence_rows, observation_rows = (
        _retained_state_table_rows(authority)
    )
    try:
        raw_stream = c2b2a_encode_retained_state_table(
            edge_rows, root_rows, entry_rows, absence_rows, observation_rows
        )
        parsed = c2b2a_parse_retained_state_table(raw_stream)
        canonical_stream = c2b2a_encode_retained_state_table(
            parsed[0], parsed[1], parsed[2], parsed[3], parsed[4]
        )
        binding = authority.retained_state_table_binding
        accepted_stream = c2b2a_validate_retained_state_table_binding(
            canonical_stream,
            binding.name,
            binding.rows,
            binding.bytes,
            binding.sha256,
        )
    except ValueError as exc:
        raise ControllerError("retained-state table binding is not canonical") from exc
    if raw_stream != canonical_stream or accepted_stream != canonical_stream:
        fail("retained-state table adapter changed its canonical bytes")
    raw_stream = b""
    return accepted_stream


def _source_audit_rule_stream(rules: Sequence[SourceAuditRule]) -> bytes:
    rows = [b"schema=c2b2a-source-audit-rules-v1\n"]
    for item in rules:
        rows.append(
            canonical_json_line(
                {
                    "rule_id": item.rule_id,
                    "claim_class": item.claim_class,
                    "source_class": item.source_class,
                    "package": item.package,
                    "version": item.version,
                    "relative_path": item.relative_path,
                    "source_sha256": item.source_sha256,
                    "start_byte": item.start_byte,
                    "end_byte": item.end_byte,
                    "span_sha256": item.span_sha256,
                    "token_hex": item.token_hex,
                    "expected_count": item.expected_count,
                    "callable": item.callable,
                    "reachability": item.reachability,
                    "activation": item.activation,
                    "disposition": item.disposition,
                }
            )
        )
    return b"".join(rows)


def _path_is_beneath(path: str, root: str) -> bool:
    return path == root or path.startswith(root + "/")


def _paths_overlap(left: str, right: str) -> bool:
    return _path_is_beneath(left, right) or _path_is_beneath(right, left)


def _validate_authority_topology(authority: Authority) -> None:
    roots = [item.path for item in authority.tool_roots]
    for index, left in enumerate(roots):
        for right in roots[index + 1 :]:
            if _paths_overlap(left, right):
                fail("tool roots overlap")
    for system in authority.system_inputs:
        for root in roots:
            if _paths_overlap(system.path, root):
                fail("system input overlaps a tool root")
    systems = list(authority.system_inputs)
    for index, left in enumerate(systems):
        for right in systems[index + 1 :]:
            if _paths_overlap(left.path, right.path):
                ancestor = left if _path_is_beneath(right.path, left.path) else right
                if not ancestor.traversal:
                    fail("system-input ancestry lacks traversal authority")


def _validate_relative_path(path: str) -> None:
    raw = raw_key(path)
    if len(raw) > 4096 or len(path.split("/")) > 128:
        fail("relative path exceeds a frozen bound")
    if path.startswith("/") or "\\" in path:
        fail("relative path is absolute or contains a backslash")
    if any(part in ("", ".", "..") for part in path.split("/")):
        fail("relative path has an invalid component")


def _file_digest_from_fd(
    fd: int, *, maximum: int = U64_MAX
) -> tuple[int, str]:
    if type(maximum) is not int or maximum < 0 or maximum > U64_MAX:
        fail("file digest byte ceiling is outside u64")
    before = os.fstat(fd)
    if not stat.S_ISREG(before.st_mode):
        fail("tree file is not regular")
    if before.st_size < 0 or before.st_size > maximum:
        fail("tree file size is outside its pre-read byte ceiling")
    digest = hashlib.sha256()
    size = 0
    os.lseek(fd, 0, os.SEEK_SET)
    while size < before.st_size:
        chunk = os.read(fd, min(1 << 20, before.st_size - size))
        if not chunk:
            fail("tree file ended before its reserved byte count")
        size = checked_add(size, len(chunk), maximum)
        digest.update(chunk)
    if os.read(fd, 1):
        fail("tree file grew beyond its reserved byte count")
    after = os.fstat(fd)
    if not _same_identity(before, after) or (
        before.st_mode,
        before.st_nlink,
        before.st_size,
        before.st_mtime_ns,
        before.st_ctime_ns,
    ) != (
        after.st_mode,
        after.st_nlink,
        after.st_size,
        after.st_mtime_ns,
        after.st_ctime_ns,
    ):
        fail("tree file changed while hashed")
    if size != before.st_size:
        fail("tree file size mismatch")
    return size, digest.hexdigest()


