    parsed_groups = [[], [], [], [], []]
    for line_index in range(1, 75):
        if line_index <= 3:
            group_index = 0
            keys = (
                "kind",
                "sequence",
                "edge",
                "producer_phase",
                "producer_boundary",
                "consumer_phase",
                "consumer_boundary",
            )
        elif line_index <= 32:
            group_index = 1
            keys = ("kind", "edge_sequence", "sequence", "class", "path", "scope")
