def _host_exact_commands(authority: Authority, phase: str) -> tuple[tuple[str, ...], ...]:
    commands = _exact_commands(authority, phase)
    paths = _host_validation_paths(authority)
    if phase == "host-validation-payload-tests":
        expected = _expected_payload_test_commands(authority)
    elif phase == "host-validation-foundation-test-run":
        expected = (
            (paths["test-bin"], "--test-threads=1"),
            (paths["test-bin"], "--test-threads=4"),
        )
    elif phase == "host-validation-foundation-bin-run":
        expected = ((paths["bin"],),)
    elif phase == "host-validation-lints":
        expected = _expected_lint_commands(authority)
    elif phase in (
        "host-validation-foundation-test-compile",
        "host-validation-foundation-bin-compile",
    ):
        if len(commands) != 1:
            fail("foundation compile command count is not one")
        command = commands[0]
        source = (
            REPOSITORY + "/engram-eval/tests/native_c2b2a_foundation.rs"
            if phase.endswith("test-compile")
            else REPOSITORY + "/engram-eval/src/bin/native-c2b2a.rs"
        )
        output = paths["test-bin"] if phase.endswith("test-compile") else paths["bin"]
        prefix = (authority.tools["rustc"].path, "--edition=2021")
        if phase.endswith("test-compile"):
            prefix = (*prefix, "--test")
        if tuple(command[: len(prefix) + 1]) != (*prefix, source):
            fail("foundation compile source/prefix is not exact")
        extern_rows: list[tuple[str, str]] = []
        for index, value in enumerate(command):
            if value == "--extern":
                if index + 1 >= len(command) or "=" not in command[index + 1]:
                    fail("foundation compile has a malformed --extern")
                name, path = command[index + 1].split("=", 1)
                extern_rows.append((name, path))
        if tuple(name for name, _path in extern_rows) != ("sha2", "serde", "thiserror"):
            fail("foundation compile extern set or order is not exact")
        for name, path in extern_rows:
            canonical_absolute_lexical(path)
            if (
                os.path.dirname(path) != paths["deps"]
                or not os.path.basename(path).startswith("lib" + name + "-")
                or not path.endswith(".rlib")
            ):
                fail("foundation compile extern path is outside the exact dependency closure")
        crate_name = "native_c2b2a_foundation" if phase.endswith("test-compile") else "native_c2b2a"
        expected = ((
            *prefix,
            source,
            "--crate-name",
            crate_name,
            *(value for pair in extern_rows for value in ("--extern", pair[0] + "=" + pair[1])),
            "-L",
            "dependency=" + paths["deps"],
            "--remap-path-prefix",
            REPOSITORY + "=/c2b2a-repository",
            "-D",
            "warnings",
            "-o",
            output,
        ),)
    else:
        fail("unknown exact host-validation command phase")
    if commands != expected:
        fail("host-validation command table differs from the frozen exact schedule")
    return commands


def _decode_host_output(data: bytes, label: str, *, allow_empty: bool) -> str:
    if len(data) > STREAM_LIMIT or b"\x00" in data:
        fail(label + " output exceeds its bound or contains NUL")
    if not data:
        if allow_empty:
            return ""
        fail(label + " output is unexpectedly empty")
    try:
        text = data.decode("utf-8", "strict")
    except UnicodeError as exc:
        raise ControllerError(label + " output is not UTF-8") from exc
    if "\r" in text or not text.endswith("\n"):
        fail(label + " output does not use canonical LF framing")
    return text


def _parse_libtest_result(data: bytes, expected_passed: int) -> dict[str, int]:
    text = _decode_host_output(data, "libtest", allow_empty=False)
    matches = re.findall(
        r"(?m)^test result: ok\. ([0-9]+) passed; ([0-9]+) failed; "
        r"([0-9]+) ignored; [0-9]+ measured; ([0-9]+) filtered out; finished in [^\n]+$",
        text,
    )
    if len(matches) != 1:
        fail("libtest output does not contain exactly one canonical success summary")
    passed, failed, ignored, filtered = tuple(int(value) for value in matches[0])
    if (passed, failed, ignored, filtered) != (expected_passed, 0, 0, 0):
        fail("libtest counts differ from the frozen expectation")
    return {
        "passed": passed,
        "failed": failed,
        "ignored": ignored,
        "filtered": filtered,
    }


def _reject_warning_output(result: ChildResult) -> None:
    combined = result.stdout + b"\n" + result.stderr
    if re.search(rb"(?im)(^|\n)warning(?:\[[^\]]+\])?:", combined):
        fail("host-validation command emitted a warning")


def _seal_host_generated_tree(root: str) -> dict[str, Any]:
    xattr_capability = _generated_xattr_capability(
        CURRENT_AUTHORITY, root, "host-sealed-tree"
    )
    root_xattr_capability = _xattr_object_capability(
        CURRENT_AUTHORITY, xattr_capability, root, root=True
    )
    _verify_owner_only_generated_tree(root, xattr_capability)
    root_fd = _open_directory_nofollow(root)
    seen: set[tuple[int, int]] = set()
    try:
        def seal(fd: int, absolute: str) -> None:
            names = sorted(os.listdir(fd), key=raw_key)
            for name in names:
                child_path = absolute + "/" + name
                child_xattr_capability = _xattr_object_capability(
                    CURRENT_AUTHORITY,
                    xattr_capability,
                    child_path,
                    root=False,
                )
                info = os.stat(name, dir_fd=fd, follow_symlinks=False)
                flags = os.O_RDONLY | os.O_CLOEXEC | getattr(os, "O_NOFOLLOW", 0)
                if stat.S_ISDIR(info.st_mode):
                    flags |= os.O_DIRECTORY
                elif not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
                    fail("host target contains a forbidden object")
                child = os.open(name, flags, dir_fd=fd)
                try:
                    opened = _assert_generated_fd(
                        child, CURRENT_AUTHORITY, child_xattr_capability
                    )
                    if not _full_identity_equal(info, opened):
                        fail("host target object changed while sealing")
                    key = (opened.st_dev, opened.st_ino)
                    if key in seen:
                        fail("host target contains a shared inode")
                    seen.add(key)
                    if stat.S_ISDIR(opened.st_mode):
                        seal(child, child_path)
                        final_mode = 0o500
                    else:
                        final_mode = 0o500 if opened.st_mode & 0o111 else 0o400
                        os.fchmod(child, final_mode)
                        os.utime(child, ns=(0, 0))
                        os.fsync(child)
                    sealed = _assert_generated_fd(
                        child, CURRENT_AUTHORITY, child_xattr_capability
                    )
                    if (
                        not _same_identity(opened, sealed)
                        or sealed.st_uid != opened.st_uid
                        or sealed.st_gid != opened.st_gid
                        or sealed.st_nlink != opened.st_nlink
                        or sealed.st_size != opened.st_size
                        or getattr(sealed, "st_flags", 0)
                        != getattr(opened, "st_flags", 0)
                        or stat.S_IMODE(sealed.st_mode) != final_mode
                        or sealed.st_mtime_ns != 0
                    ):
                        fail("host target object seal transition is not exact")
                finally:
                    os.close(child)
            os.fchmod(fd, 0o500)
            os.utime(fd, ns=(0, 0))
            os.fsync(fd)

        root_before = _assert_generated_fd(
            root_fd, CURRENT_AUTHORITY, root_xattr_capability
        )
        seal(root_fd, root)
        root_after = _assert_generated_fd(
            root_fd, CURRENT_AUTHORITY, root_xattr_capability
        )
        if (
            not _same_identity(root_before, root_after)
            or root_after.st_uid != root_before.st_uid
            or root_after.st_gid != root_before.st_gid
            or getattr(root_after, "st_flags", 0)
            != getattr(root_before, "st_flags", 0)
            or stat.S_IMODE(root_after.st_mode) != 0o500
            or root_after.st_mtime_ns != 0
        ):
            fail("host target root seal transition is not exact")
    finally:
        os.close(root_fd)
    sidecar = _canonical_xattr_sidecar_stream(
        CURRENT_AUTHORITY, root, xattr_capability, None
    )
    raw_sidecar_stream = sidecar.stream
    parsed_sidecar = c2b2a_parse_xattr_sidecar(raw_sidecar_stream)
    canonical_sidecar_stream = c2b2a_encode_xattr_sidecar(parsed_sidecar)
    canonical_sidecar_rows = canonical_sidecar_stream.count(b"\n")
    canonical_sidecar_bytes = len(canonical_sidecar_stream)
    canonical_sidecar_sha256 = sha256_bytes(canonical_sidecar_stream)
    if (
        canonical_sidecar_stream != raw_sidecar_stream
        or (
            canonical_sidecar_rows,
            canonical_sidecar_bytes,
            canonical_sidecar_sha256,
        )
        != (sidecar.rows, sidecar.bytes, sidecar.sha256)
    ):
        fail("sealed host sidecar did not reconstruct its canonical source")
    raw_sidecar_stream = b""
    return {
        "path": root,
        "objects": len(parsed_sidecar),
        "xattr_rows": canonical_sidecar_rows,
        "xattr_bytes": canonical_sidecar_bytes,
        "xattr_sha256": canonical_sidecar_sha256,
    }


def _fingerprint_units(authority: Authority) -> list[dict[str, Any]]:
    paths = _host_validation_paths(authority)
    payload_tests_xattr_capability = _generated_xattr_capability(
        authority, paths["payload-tests"], "host-sealed-tree"
    )
    fingerprint_root = paths["payload-tests"] + "/debug/.fingerprint"
    deps_root = paths["payload-tests"] + "/debug/deps"
    bundle_root = authority.acquisition_root + "/sealed-archives"
    bundle_xattr_capability = _generated_xattr_capability(
        authority, bundle_root, "archive-tree"
    )
    manifest_rows = _parse_manifest_rows(
        _read_xattr_regular(
            authority,
            bundle_root + "/archive-manifest-v1.tsv",
            bundle_xattr_capability,
            1_048_576,
        )
    )
    units: list[dict[str, Any]] = []
    fingerprint_root_xattr_capability = _xattr_object_capability(
        authority,
        payload_tests_xattr_capability,
        fingerprint_root,
        root=False,
    )
    deps_root_xattr_capability = _xattr_object_capability(
        authority,
        payload_tests_xattr_capability,
        deps_root,
        root=False,
    )
    deps_fd = _open_directory_nofollow(deps_root)
    deps_before = _validate_xattr_object_fd(
        deps_fd,
        authority,
        deps_root_xattr_capability,
        expected_uid=os.getuid(),
        expected_gid=os.getgid(),
    )
    if stat.S_IMODE(deps_before.st_mode) != 0o500 or deps_before.st_mtime_ns != 0:
        os.close(deps_fd)
        fail("Cargo dependency artifact root is not in its exact sealed state")
    deps_names = sorted(os.listdir(deps_fd), key=raw_key)
    if len(deps_names) != len(set(deps_names)):
        os.close(deps_fd)
        fail("Cargo dependency artifact root contains duplicate entries")

    def read_dependency_artifact(path: str, maximum: int) -> bytes:
        if os.path.dirname(path) != deps_root:
            fail("Cargo dependency artifact is outside its exact deps root")
        name = os.path.basename(path)
        if name not in deps_names or name in ("", ".", ".."):
            fail("Cargo dependency artifact is absent from its stable sibling inventory")
        artifact_xattr_capability = _xattr_object_capability(
            authority,
            payload_tests_xattr_capability,
            path,
            root=False,
        )
        artifact_lstat = os.stat(name, dir_fd=deps_fd, follow_symlinks=False)
        artifact_fd = os.open(
            name,
            os.O_RDONLY | os.O_CLOEXEC | getattr(os, "O_NOFOLLOW", 0),
            dir_fd=deps_fd,
        )
        try:
            artifact_info = _validate_xattr_object_fd(
                artifact_fd,
                authority,
                artifact_xattr_capability,
                expected_uid=os.getuid(),
                expected_gid=os.getgid(),
            )
            if (
                not _full_identity_equal(artifact_lstat, artifact_info)
                or not stat.S_ISREG(artifact_info.st_mode)
                or artifact_info.st_nlink != 1
                or stat.S_IMODE(artifact_info.st_mode) != 0o400
                or artifact_info.st_mtime_ns != 0
            ):
                fail("Cargo dependency artifact is not an exact sealed file")
            return _read_regular_fd(artifact_fd, maximum=maximum)
        finally:
            os.close(artifact_fd)

    root_fd = _open_directory_nofollow(fingerprint_root)
    root_before: os.stat_result | None = None
    root_names: list[str] = []
    try:
        root_before = _validate_xattr_object_fd(
            root_fd,
            authority,
            fingerprint_root_xattr_capability,
            expected_uid=os.getuid(),
            expected_gid=os.getgid(),
        )
        if stat.S_IMODE(root_before.st_mode) != 0o500 or root_before.st_mtime_ns != 0:
            fail("Cargo fingerprint root is not in its exact sealed state")
        root_names = sorted(os.listdir(root_fd), key=raw_key)
        if len(root_names) != len(set(root_names)):
            fail("Cargo fingerprint root contains duplicate entries")
        for directory in root_names:
            match = re.fullmatch(r"(.+)-([0-9a-f]{16})", directory)
            if match is None:
                fail("Cargo fingerprint directory has an unknown name")
            directory_path = fingerprint_root + "/" + directory
            directory_xattr_capability = _xattr_object_capability(
                authority,
                payload_tests_xattr_capability,
                directory_path,
                root=False,
            )
            directory_lstat = os.stat(
                directory, dir_fd=root_fd, follow_symlinks=False
            )
            directory_fd = os.open(
                directory,
                os.O_RDONLY
                | os.O_DIRECTORY
                | os.O_CLOEXEC
                | getattr(os, "O_NOFOLLOW", 0),
                dir_fd=root_fd,
            )
            try:
                directory_before = _validate_xattr_object_fd(
                    directory_fd,
                    authority,
                    directory_xattr_capability,
                    expected_uid=os.getuid(),
                    expected_gid=os.getgid(),
                )
                if (
                    not _full_identity_equal(directory_lstat, directory_before)
                    or not stat.S_ISDIR(directory_before.st_mode)
                    or stat.S_IMODE(directory_before.st_mode) != 0o500
                    or directory_before.st_mtime_ns != 0
                ):
                    fail("Cargo fingerprint directory is not in its exact sealed state")
                names = sorted(os.listdir(directory_fd), key=raw_key)
                if len(names) != len(set(names)):
                    fail("Cargo fingerprint directory contains duplicate entries")

                def read_member(name: str, maximum: int) -> bytes:
                    if name not in names or "/" in name or name in ("", ".", ".."):
                        fail("Cargo fingerprint member is outside its stable sibling inventory")
                    member_path = directory_path + "/" + name
                    member_xattr_capability = _xattr_object_capability(
                        authority,
                        payload_tests_xattr_capability,
                        member_path,
                        root=False,
                    )
                    member_lstat = os.stat(
                        name, dir_fd=directory_fd, follow_symlinks=False
                    )
                    member_fd = os.open(
                        name,
                        os.O_RDONLY
                        | os.O_CLOEXEC
                        | getattr(os, "O_NOFOLLOW", 0),
                        dir_fd=directory_fd,
                    )
                    try:
                        member_info = _validate_xattr_object_fd(
                            member_fd,
                            authority,
                            member_xattr_capability,
                            expected_uid=os.getuid(),
                            expected_gid=os.getgid(),
                        )
                        if (
                            not _full_identity_equal(member_lstat, member_info)
                            or not stat.S_ISREG(member_info.st_mode)
                            or member_info.st_nlink != 1
                            or stat.S_IMODE(member_info.st_mode) != 0o400
                            or member_info.st_mtime_ns != 0
                        ):
                            fail("Cargo fingerprint member is not an exact sealed file")
                        return _read_regular_fd(member_fd, maximum=maximum)
                    finally:
                        os.close(member_fd)

                json_names = []
                for name in names:
                    if not name.endswith(".json"):
                        continue
                    if (
                        name.startswith("lib-")
                        or name.startswith("proc-macro-")
                        or name == "test-integration-test-rocks.json"
                    ):
                        json_names.append(name)
                for json_name in json_names:
                    if json_name.startswith("proc-macro-"):
                        kind = "proc-macro"
                        prefix = "proc-macro-"
                    elif json_name.startswith("lib-"):
                        kind = "lib"
                        prefix = "lib-"
                    else:
                        kind = "rocks-test-root"
                        prefix = "test-integration-test-"
                    crate = json_name[len(prefix) : -5]
                    raw_key(crate)
                    json_path = fingerprint_root + "/" + directory + "/" + json_name
                    raw = read_member(json_name, 16_777_216)
                    try:
                        record = json.loads(raw.decode("utf-8", "strict"))
                    except (UnicodeError, json.JSONDecodeError) as exc:
                        raise ControllerError("Cargo fingerprint JSON is invalid") from exc
                    if not isinstance(record, dict) or set(record) != {
                        "rustc",
                        "features",
                        "declared_features",
                        "target",
                        "profile",
                        "path",
                        "deps",
                        "local",
                        "rustflags",
                        "config",
                        "compile_kind",
                    }:
                        fail("Cargo fingerprint JSON does not have its exact pinned schema")
                    for integer_field in (
                        "rustc",
                        "target",
                        "profile",
                        "path",
                        "config",
                        "compile_kind",
                    ):
                        if not isinstance(record[integer_field], int) or isinstance(
                            record[integer_field], bool
                        ):
                            fail("Cargo fingerprint integer field has the wrong type")
                    if not isinstance(record["declared_features"], str) or not isinstance(
                        record["local"], list
                    ):
                        fail("Cargo fingerprint auxiliary field has the wrong type")
                    if not isinstance(record["rustflags"], list) or not all(
                        isinstance(item, str) for item in record["rustflags"]
                    ):
                        fail("Cargo fingerprint rustflags field is not a string array")
                    features_raw = record.get("features")
                    if not isinstance(features_raw, str):
                        fail("Cargo fingerprint feature encoding is absent")
                    try:
                        features = json.loads(features_raw)
                    except json.JSONDecodeError as exc:
                        raise ControllerError("Cargo fingerprint features are invalid") from exc
                    if (
                        not isinstance(features, list)
                        or not all(isinstance(item, str) for item in features)
                        or features != sorted(set(features), key=raw_key)
                    ):
                        fail("Cargo fingerprint features are not a canonical string array")
                    deps = record.get("deps")
                    if not isinstance(deps, list):
                        fail("Cargo fingerprint dependency array is absent")
                    dependency_rows: list[tuple[str, int]] = []
                    for dep in deps:
                        if (
                            not isinstance(dep, list)
                            or len(dep) != 4
                            or not isinstance(dep[0], int)
                            or isinstance(dep[0], bool)
                            or not isinstance(dep[1], str)
                            or not isinstance(dep[2], bool)
                            or not isinstance(dep[3], int)
                            or isinstance(dep[3], bool)
                            or dep[0] < 0
                            or dep[0] > U64_MAX
                            or dep[3] < 0
                            or dep[3] > U64_MAX
                        ):
                            fail("Cargo fingerprint dependency row is invalid")
                        raw_key(dep[1])
                        dependency_rows.append((dep[1], dep[3]))
                    local = record.get("local")
                    dep_info_paths: list[str] = []
                    if not isinstance(local, list):
                        fail("Cargo fingerprint local array is absent")
                    for item in local:
                        if not isinstance(item, dict) or set(item) != {"CheckDepInfo"}:
                            continue
                        check = item["CheckDepInfo"]
                        if not isinstance(check, dict) or not isinstance(
                            check.get("dep_info"), str
                        ):
                            fail("Cargo fingerprint dep-info authority is invalid")
                        dep_info = check["dep_info"]
                        if dep_info.startswith("/"):
                            fail("Cargo fingerprint dep-info path is unexpectedly absolute")
                        _validate_relative_path(dep_info)
                        dep_info_path = paths["payload-tests"] + "/" + dep_info
                        if (
                            os.path.dirname(dep_info_path) != directory_path
                            or os.path.basename(dep_info_path) not in names
                            or not os.path.basename(dep_info_path).startswith("dep-")
                        ):
                            fail(
                                "Cargo fingerprint dep-info path is outside its exact sibling grammar"
                            )
                        dep_info_paths.append(dep_info_path)
                    if len(dep_info_paths) != 1:
                        fail("Cargo fingerprint lacks one exact dep-info path")
                    dep_info_data = read_member(
                        os.path.basename(dep_info_paths[0]), 67_108_864
                    )
                    package_matches = []
                    for name, version, _source, _basename, _size, _digest in manifest_rows:
                        source_prefix = (
                            authority.root_a
                            + "/cargo-source/"
                            + name
                            + "-"
                            + version
                            + "/"
                        ).encode("utf-8")
                        if source_prefix in dep_info_data:
                            package_matches.append((name, version))
                    if kind == "rocks-test-root":
                        expected_test_source = (
                            authority.root_a + "/payload/tests/rocks.rs"
                        ).encode("utf-8")
                        if package_matches or expected_test_source not in dep_info_data:
                            fail("collector rocks-test fingerprint lacks its exact payload source")
                        package = "engram-native-c2b2a-payload"
                        version = "0.0.0"
                        artifact = "-"
                    else:
                        if len(package_matches) != 1:
                            fail("Cargo fingerprint dep-info lacks one package/version source")
                        package, version = package_matches[0]
                        extension = ".dylib" if kind == "proc-macro" else ".rlib"
                        artifact = (
                            deps_root
                            + "/lib"
                            + crate
                            + "-"
                            + match.group(2)
                            + extension
                        )
                        canonical_absolute_lexical(artifact)
                    fingerprint_name = json_name[:-5]
                    if fingerprint_name not in names:
                        fail("Cargo fingerprint JSON lacks its exact short-hash sibling")
                    fingerprint_path = fingerprint_root + "/" + directory + "/" + fingerprint_name
                    fingerprint_bytes = read_member(fingerprint_name, 17)
                    try:
                        fingerprint_text = fingerprint_bytes.decode("ascii", "strict")
                    except UnicodeError as exc:
                        raise ControllerError("Cargo short fingerprint is not ASCII") from exc
                    if re.fullmatch(r"[0-9a-f]{16}", fingerprint_text) is None:
                        fail("Cargo short fingerprint is not exact lowercase u64 hex")
                    fingerprint_u64 = int.from_bytes(
                        bytes.fromhex(fingerprint_text), "little"
                    )
                    units.append(
                        {
                            "package": package,
                            "version": version,
                            "crate": crate,
                            "kind": kind,
                            "crate_target": "lib" if kind in ("lib", "proc-macro") else "test",
                            "compile_kind": "host",
                            "dependency_role": "normal",
                            "profile": "debug-nontest" if kind in ("lib", "proc-macro") else "debug-test",
                            "suffix": match.group(2),
                            "features_sha256": sha256_bytes(canonical_json_line(features)),
                            "dependencies": tuple(dependency_rows),
                            "fingerprint": json_path,
                            "fingerprint_sha256": sha256_bytes(raw),
                            "fingerprint_value_path": fingerprint_path,
                            "fingerprint_value_sha256": sha256_bytes(fingerprint_bytes),
                            "fingerprint_u64": fingerprint_u64,
                            "artifact": artifact,
                            "artifact_sha256": (
                                sha256_bytes(
                                    read_dependency_artifact(artifact, 536_870_912)
                                )
                                if artifact != "-"
                                else "-"
                            ),
                        }
                    )
                directory_after = _validate_xattr_object_fd(
                    directory_fd,
                    authority,
                    directory_xattr_capability,
                    expected_uid=os.getuid(),
                    expected_gid=os.getgid(),
                )
                if (
                    not _full_identity_equal(directory_before, directory_after)
                    or names != sorted(os.listdir(directory_fd), key=raw_key)
                ):
                    fail("Cargo fingerprint directory changed during observation")
            finally:
                os.close(directory_fd)
    finally:
        try:
            root_after = _validate_xattr_object_fd(
                root_fd,
                authority,
                fingerprint_root_xattr_capability,
                expected_uid=os.getuid(),
                expected_gid=os.getgid(),
            )
            deps_after = _validate_xattr_object_fd(
                deps_fd,
                authority,
                deps_root_xattr_capability,
                expected_uid=os.getuid(),
                expected_gid=os.getgid(),
            )
            if (
                root_before is None
                or not _full_identity_equal(root_before, root_after)
                or root_names != sorted(os.listdir(root_fd), key=raw_key)
                or not _full_identity_equal(deps_before, deps_after)
                or deps_names != sorted(os.listdir(deps_fd), key=raw_key)
            ):
                fail("Cargo fingerprint or dependency inventory changed during observation")
        finally:
            os.close(root_fd)
            os.close(deps_fd)
    units.sort(
        key=lambda item: (
            raw_key(item["artifact"]),
            raw_key(item["fingerprint"]),
        )
    )
    roots = [item for item in units if item["kind"] == "rocks-test-root"]
    if (
        len(roots) != 1
        or roots[0]["crate"] != "rocks"
        or roots[0]["features_sha256"]
        != sha256_bytes(canonical_json_line(["collector"]))
    ):
        fail("Cargo fingerprints lack one exact collector rocks-test root")
    by_fingerprint: dict[int, list[dict[str, Any]]] = {}
    for unit in units:
        by_fingerprint.setdefault(unit["fingerprint_u64"], []).append(unit)
    reachable = {roots[0]["fingerprint"]}
    pending = [roots[0]]
    while pending:
        unit = pending.pop(0)
        for dependency_name, dependency_hash in unit["dependencies"]:
            if dependency_name == "build_script_build":
                continue
            candidates = by_fingerprint.get(dependency_hash, [])
            if len(candidates) != 1:
                fail("Cargo normal fingerprint edge is missing or ambiguous")
            candidate = candidates[0]
            if candidate["kind"] not in ("lib", "proc-macro"):
                fail("Cargo normal fingerprint edge reaches a forbidden target kind")
            if candidate["fingerprint"] not in reachable:
                reachable.add(candidate["fingerprint"])
                pending.append(candidate)
    for unit in units:
        unit["normal_rocks_reachable"] = unit["fingerprint"] in reachable
    return units


def _foundation_extern_paths(command: Sequence[str]) -> dict[str, str]:
    result: dict[str, str] = {}
    for index, value in enumerate(command):
        if value != "--extern":
            continue
        name, path = command[index + 1].split("=", 1)
        if name in result:
            fail("foundation compile repeats an extern")
        result[name] = path
    if tuple(result) != ("sha2", "serde", "thiserror"):
        fail("foundation extern order is not exact")
    return result


def _select_foundation_dependencies(
    authority: Authority, command: Sequence[str]
) -> tuple[list[dict[str, Any]], TreeIdentity]:
    paths = _host_validation_paths(authority)
    deps_xattr_capability = _foundation_traversal_xattr_capability(
        authority, paths["deps"]
    )
    payload_tests_xattr_capability = _generated_xattr_capability(
        authority, paths["payload-tests"], "host-sealed-tree"
    )
    units = _fingerprint_units(authority)
    selected: dict[str, dict[str, Any]] = {}
    rejected: dict[str, list[dict[str, str]]] = {}
    for selector in authority.host_dependency_selectors:
        candidates = [
            unit
            for unit in units
            if unit["package"] == selector.name
            and unit["version"] == selector.version
            and unit["crate"] == selector.name.replace("-", "_")
            and unit["kind"] == "lib"
            and unit["crate_target"] == selector.crate_target
            and unit["compile_kind"] == selector.compile_kind
            and unit["dependency_role"] == selector.dependency_role
            and unit["profile"] == selector.profile
            and unit["features_sha256"] == selector.features_sha256
            and unit["normal_rocks_reachable"]
        ]
        if not candidates:
            fail("host dependency selector matched no Cargo fingerprint unit")
        candidates.sort(key=lambda item: raw_key(os.path.basename(item["artifact"])))
        selected[selector.name] = candidates[0]
        rejected[selector.name] = [
            {
                "artifact": os.path.basename(item["artifact"]),
                "sha256": item["artifact_sha256"],
            }
            for item in candidates[1:]
        ]
    pending = list(selected.values())
    closure: dict[str, dict[str, Any]] = {
        item["artifact"]: item for item in pending
    }
    while pending:
        unit = pending.pop(0)
        for dependency_name, dependency_hash in unit["dependencies"]:
            if dependency_name == "build_script_build":
                continue
            candidates = [
                item
                for item in units
                if item["fingerprint_u64"] == dependency_hash
                and item["normal_rocks_reachable"]
                and item["kind"] in ("lib", "proc-macro")
            ]
            if len(candidates) != 1:
                fail("host dependency fingerprint edge is missing or ambiguous")
            candidate = candidates[0]
            if candidate["artifact"] not in closure:
                closure[candidate["artifact"]] = candidate
                pending.append(candidate)
    externs = _foundation_extern_paths(command)
    for name, unit in selected.items():
        if os.path.basename(externs[name]) != os.path.basename(unit["artifact"]):
            fail("foundation extern basename differs from selected Cargo unit")
    for path in sorted(closure, key=raw_key):
        destination = paths["deps"] + "/" + os.path.basename(path)
        if destination not in externs.values() and os.path.basename(destination) in {
            os.path.basename(value) for value in externs.values()
        }:
            fail("foundation dependency destination basename collides")
        _copy_create_new(
            path,
            destination,
            source_xattr_capability=payload_tests_xattr_capability,
            xattr_capability=deps_xattr_capability,
            parent_xattr_capability=deps_xattr_capability,
            final_mode=0o400,
        )
    deps_fd = _open_directory_nofollow(paths["deps"])
    try:
        names = sorted(os.listdir(deps_fd), key=raw_key)
        if names != sorted({os.path.basename(path) for path in closure}, key=raw_key):
            fail("foundation dependency copy closure has an extra or missing file")
        for name in names:
            child_xattr_capability = _xattr_object_capability(
                authority,
                deps_xattr_capability,
                paths["deps"] + "/" + name,
                root=False,
            )
            fd = os.open(
                name,
                os.O_RDONLY | os.O_CLOEXEC | getattr(os, "O_NOFOLLOW", 0),
                dir_fd=deps_fd,
            )
            try:
                info = _assert_generated_fd(
                    fd, authority, child_xattr_capability
                )
                if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
                    fail("foundation dependency copy is not a single-link file")
                os.fchmod(fd, 0o444)
                os.utime(fd, ns=(0, 0))
                os.fsync(fd)
            finally:
                os.close(fd)
        os.fchmod(deps_fd, 0o500)
        os.utime(deps_fd, ns=(0, 0))
        os.fsync(deps_fd)
    finally:
        os.close(deps_fd)
    identity = canonical_foundation_tree(paths["deps"], "foundation-deps")
    evidence = [
        {
            "package": unit["package"],
            "version": unit["version"],
            "crate": unit["crate"],
            "kind": unit["kind"],
            "crate_target": unit["crate_target"],
            "compile_kind": unit["compile_kind"],
            "dependency_role": unit["dependency_role"],
            "profile": unit["profile"],
            "source_path": unit["artifact"],
            "source_sha256": unit["artifact_sha256"],
            "destination": paths["deps"] + "/" + os.path.basename(unit["artifact"]),
            "fingerprint": unit["fingerprint"],
            "fingerprint_sha256": unit["fingerprint_sha256"],
            "fingerprint_value_path": unit["fingerprint_value_path"],
            "fingerprint_value_sha256": unit["fingerprint_value_sha256"],
            "features_sha256": unit["features_sha256"],
            "rejected_candidates": rejected.get(unit["package"], []),
        }
        for unit in sorted(closure.values(), key=lambda item: raw_key(item["artifact"]))
    ]
    return evidence, identity


def _seal_foundation_executable(
    authority: Authority,
    root: str,
    output: str,
    root_fd: int,
    xattr_capability: XattrTraversalCapability,
) -> tuple[dict[str, Any], TreeIdentity]:
    output_name = os.path.basename(output)
    if sorted(os.listdir(root_fd), key=raw_key) != [output_name]:
        fail("foundation output root does not contain exactly its one executable")
    output_xattr_capability = _xattr_object_capability(
        authority, xattr_capability, output, root=False
    )
    output_fd = os.open(
        output_name,
        os.O_RDONLY | os.O_CLOEXEC | getattr(os, "O_NOFOLLOW", 0),
        dir_fd=root_fd,
    )
    try:
        initial = _assert_generated_fd(
            output_fd, authority, output_xattr_capability
        )
        if (
            not stat.S_ISREG(initial.st_mode)
            or initial.st_nlink != 1
            or not initial.st_mode & 0o111
        ):
            fail("foundation compiler output is not one executable regular file")
        os.fchmod(output_fd, 0o555)
        os.utime(output_fd, ns=(0, 0))
        os.fsync(output_fd)
        sealed = _assert_generated_fd(
            output_fd, authority, output_xattr_capability
        )
        if (
            not _same_identity(initial, sealed)
            or stat.S_IMODE(sealed.st_mode) != 0o555
            or sealed.st_nlink != 1
            or sealed.st_size != initial.st_size
            or sealed.st_mtime_ns != 0
        ):
            fail("foundation executable seal transition is not exact")
        size, digest = _file_digest_from_fd(output_fd)
        final = _assert_generated_fd(
            output_fd, authority, output_xattr_capability
        )
        linked = os.stat(output_name, dir_fd=root_fd, follow_symlinks=False)
        if (
            not _full_identity_equal(sealed, final)
            or not _full_identity_equal(final, linked)
            or size != final.st_size
        ):
            fail("foundation executable changed during held-descriptor sealing")
        output_identity = {
            "path": output,
            "device": final.st_dev,
            "inode": final.st_ino,
            "mode": _mode_text(final.st_mode),
            "bytes": size,
            "sha256": digest,
        }
    finally:
        os.close(output_fd)
    os.fchmod(root_fd, 0o500)
    os.utime(root_fd, ns=(0, 0))
    os.fsync(root_fd)
    kind = "foundation-test" if output.endswith("native_c2b2a_foundation") else "foundation-bin"
    final = canonical_foundation_tree(root, kind)
    return output_identity, final


def _write_foundation_tree_evidence(
    evidence: Evidence, identity: TreeIdentity
) -> None:
    _pre_name, stream_name, digest_name = _tree_leaf_names(identity.kind)
    evidence.write(stream_name, identity.stream)
    evidence.write(digest_name, _tree_digest_record(identity))


def _run_host_payload_tests(
    authority: Authority, metadata: DarwinMetadataRecorder
) -> None:
    phase = "host-validation-payload-tests"
    metadata.capture("pre-host-validation-setup")
    paths = _setup_host_validation(authority)
    metadata.capture("post-host-validation-setup")
    metadata.capture("pre-host-payload-root-create")
    host_xattr_capability = _generated_xattr_capability(
        authority, paths["root"], "owner-root"
    )
    payload_tests_xattr_capability = _generated_xattr_capability(
        authority, paths["payload-tests"], "host-sealed-tree"
    )
    _mkdir_new(
        paths["payload-tests"],
        0o700,
        xattr_capability=payload_tests_xattr_capability,
        parent_traversal_capability=host_xattr_capability,
    )
    metadata.capture("post-host-payload-root-create")
    commands = _host_exact_commands(authority, phase)
    runner = PhaseRunner(authority, phase, metadata)
    runner.set_policy(_host_validation_policy(authority, phase, runner, commands))
    unexpected_graph_probe_state = runner.run_probe(
        _phase_denied_reads(authority, phase)
    )
    _require_no_graph_retained_state(unexpected_graph_probe_state)
    expected = (5, 5, 15, 15, 17, 17, 12, 12, 11, 11)
    results: list[dict[str, Any]] = []
    for ordinal, (command, passed) in enumerate(zip(commands, expected, strict=True)):
        result, unexpected_graph_child_state = runner.run_child(
            command,
            _host_validation_environment(authority, runner, command),
            authority.root_a + "/payload",
            deadline=7_200,
            cargo_family_target=paths["payload-tests"],
        )
        _require_no_graph_retained_state(unexpected_graph_child_state)
        if not result.succeeded:
            fail("host payload test command did not exit zero")
        _reject_warning_output(result)
        counts = _parse_libtest_result(result.stdout, passed)
        results.append({"ordinal": ordinal, **counts})
    executables = _realized_generated_executables(authority, phase, paths["payload-tests"])
    metadata.capture("pre-host-payload-seal")
    target = _seal_host_generated_tree(paths["payload-tests"])
    metadata.capture("post-host-payload-seal")
    runner.finish(
        True,
        [],
        {
            "commands": _root_remapped_commands(commands, authority.root_a),
            "test_results": results,
            "generated_executables": executables,
            "sealed_target": target,
            "dylib_empty": _require_host_dylib_sentinel(authority),
        },
    )


def _run_host_foundation_test_compile(
    authority: Authority, metadata: DarwinMetadataRecorder
) -> None:
    phase = "host-validation-foundation-test-compile"
    paths = _host_validation_paths(authority)
    host_xattr_capability = _generated_xattr_capability(
        authority, paths["root"], "owner-root"
    )
    foundation_xattr_capability = _foundation_traversal_xattr_capability(
        authority, paths["foundation"]
    )
    deps_xattr_capability = _foundation_traversal_xattr_capability(
        authority, paths["deps"]
    )
    test_build_xattr_capability = _foundation_traversal_xattr_capability(
        authority, paths["test-build"]
    )
    metadata.capture("pre-foundation-test-root-setup")
    _mkdir_new(
        paths["foundation"],
        0o700,
        xattr_capability=foundation_xattr_capability,
        parent_traversal_capability=host_xattr_capability,
    )
    _mkdir_new(
        paths["deps"],
        0o700,
        xattr_capability=deps_xattr_capability,
        parent_traversal_capability=foundation_xattr_capability,
    )
    _mkdir_new(
        paths["test-build"],
        0o700,
        xattr_capability=test_build_xattr_capability,
        parent_traversal_capability=foundation_xattr_capability,
    )
    metadata.capture("post-foundation-test-root-setup")
    commands = _host_exact_commands(authority, phase)
    metadata.capture("pre-foundation-dependency-selection")
    selection, deps_identity = _select_foundation_dependencies(authority, commands[0])
    metadata.capture("post-foundation-dependency-selection")
    parent_before = _foundation_parent_state(authority, paths["foundation"])
    if parent_before["mode"] != "0700" or tuple(
        (item["name"], item["mode"]) for item in parent_before["entries"]
    ) != (("deps", "0500"), ("test-build", "0700")):
        fail("foundation parent is not in its exact pre-test-compile state")
    output_fd = _open_directory_nofollow(paths["test-build"])
    try:
        pre_probe = _foundation_output_root_state_fd(
            authority,
            output_fd,
            paths["test-build"],
            "pre_probe",
            test_build_xattr_capability,
        )
        if pre_probe["mode"] != "0700" or os.listdir(output_fd):
            fail("foundation test output root is not empty before compile")
        runner = PhaseRunner(authority, phase, metadata)
        runner.set_policy(_host_validation_policy(authority, phase, runner, commands))
        unexpected_graph_probe_state = runner.run_probe(
            _phase_denied_reads(authority, phase)
        )
        _require_no_graph_retained_state(unexpected_graph_probe_state)
        post_probe = _foundation_output_root_state_fd(
            authority,
            output_fd,
            paths["test-build"],
            "post_probe",
            test_build_xattr_capability,
        )
        if (
            {**pre_probe, "stage": "post_probe"} != post_probe
            or os.listdir(output_fd)
        ):
            fail("foundation policy probe changed the test output root")
        pre = _foundation_output_root_state_fd(
            authority,
            output_fd,
            paths["test-build"],
            "pre_child",
            test_build_xattr_capability,
        )
        if {**post_probe, "stage": "pre_child"} != pre:
            fail("foundation test output root changed before compile")
        _verify_foundation_repository_reads(phase)
        result, unexpected_graph_child_state = runner.run_child(
            commands[0],
            _host_validation_environment(authority, runner, commands[0]),
            authority.root_a + "/payload",
            deadline=1_800,
            allowed_tree_deltas=frozenset({"foundation-test"}),
        )
        _require_no_graph_retained_state(unexpected_graph_child_state)
        if not result.succeeded or result.stderr:
            fail("foundation test compile did not exit zero with empty stderr")
        post = _foundation_output_root_state_fd(
            authority,
            output_fd,
            paths["test-build"],
            "post_child",
            test_build_xattr_capability,
        )
        if {**pre, "stage": "post_child"} != post:
            fail("foundation test compiler changed output-root metadata")
        metadata.capture("pre-foundation-test-output-seal")
        output, test_identity = _seal_foundation_executable(
            authority,
            paths["test-build"],
            paths["test-bin"],
            output_fd,
            test_build_xattr_capability,
        )
        metadata.capture("post-foundation-test-output-seal")
        final = _foundation_output_root_state_fd(
            authority,
            output_fd,
            paths["test-build"],
            "final",
            test_build_xattr_capability,
        )
    finally:
        os.close(output_fd)
    if (
        {key: value for key, value in post.items() if key not in ("stage", "mode")}
        != {key: value for key, value in final.items() if key not in ("stage", "mode")}
        or pre["mode"] != "0700"
        or post["mode"] != "0700"
        or final["mode"] != "0500"
    ):
        fail("foundation test output-root seal transition is not exact")
    parent_after = _foundation_parent_state(authority, paths["foundation"])
    if parent_after["mode"] != "0700" or tuple(
        (item["name"], item["mode"]) for item in parent_after["entries"]
    ) != (("deps", "0500"), ("test-build", "0500")):
        fail("foundation parent is not in its exact post-test state")
    if canonical_foundation_tree(
        paths["deps"], "foundation-deps"
    ).stream != deps_identity.stream:
        fail("foundation dependency closure changed around test compilation")
    _write_foundation_tree_evidence(runner.evidence, test_identity)
    runner.finish(
        True,
        [],
        {
            "commands": [list(commands[0])],
            "dependency_selection": selection,
            "output": output,
            "output_root_states": [pre, post, final],
            "foundation_parent_after_test": parent_after,
            "dylib_empty": _require_host_dylib_sentinel(authority),
        },
    )


def _foundation_parent_checks_for_children(
    authority: Authority,
    runner: PhaseRunner,
    commands: Sequence[Sequence[str]],
    expected_state: Mapping[str, Any],
    expected_tests: Sequence[int | None],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    paths = _host_validation_paths(authority)
    foundation_xattr_capability = _foundation_traversal_xattr_capability(
        authority, paths["foundation"]
    )
    parent_fd = _open_directory_nofollow(paths["foundation"])
    checks: list[dict[str, Any]] = []
    results: list[dict[str, Any]] = []
    try:
        for ordinal, (command, expected_passed) in enumerate(
            zip(commands, expected_tests, strict=True)
        ):
            pre = _foundation_parent_state_fd(
                authority,
                parent_fd,
                paths["foundation"],
                foundation_xattr_capability,
            )
            if pre != expected_state:
                fail("foundation parent differs from its sealed prior authority")
            result, unexpected_graph_child_state = runner.run_child(
                command,
                _host_validation_environment(authority, runner, command),
                authority.root_a + "/payload",
                deadline=1_800 if runner.phase != "host-validation-lints" else (
                    300 if ordinal == 7 else 7_200
                ),
                cargo_family_target=(paths["lints"] if runner.phase == "host-validation-lints" and ordinal < 7 else None),
            )
            _require_no_graph_retained_state(unexpected_graph_child_state)
            if not result.succeeded:
                fail("host foundation/lint command did not exit zero")
            if runner.phase in (
                "host-validation-foundation-test-run",
                "host-validation-foundation-bin-run",
            ) and result.stderr:
                fail("host foundation executable emitted stderr")
            _reject_warning_output(result)
            post = _foundation_parent_state_fd(
                authority,
                parent_fd,
                paths["foundation"],
                foundation_xattr_capability,
            )
            if post != pre:
                fail("foundation parent changed around a substantive child")
            checks.append({"ordinal": ordinal, "pre": pre, "post": post})
            if expected_passed is not None:
                results.append({"ordinal": ordinal, **_parse_libtest_result(result.stdout, expected_passed)})
            else:
                results.append(
                    {
                        "ordinal": ordinal,
                        "stdout_sha256": sha256_bytes(result.stdout),
                        "stderr_sha256": sha256_bytes(result.stderr),
                    }
                )
    finally:
        os.close(parent_fd)
    return checks, results


def _read_prior_foundation_state(
    authority: Authority, phase: str, field: str
) -> dict[str, Any]:
    result = _read_valid_phase_result(authority, phase)
    observations = result.get("observations")
    if not isinstance(observations, dict) or not isinstance(observations.get(field), dict):
        fail("prior foundation result lacks its exact parent state")
    return observations[field]


def _run_host_foundation_test_run(
    authority: Authority, metadata: DarwinMetadataRecorder
) -> None:
    phase = "host-validation-foundation-test-run"
    commands = _host_exact_commands(authority, phase)
    expected_parent = _read_prior_foundation_state(
        authority, "host-validation-foundation-test-compile", "foundation_parent_after_test"
    )
    runner = PhaseRunner(authority, phase, metadata)
    runner.set_policy(_host_validation_policy(authority, phase, runner, commands))
    unexpected_graph_probe_state = runner.run_probe(
        _phase_denied_reads(authority, phase)
    )
    _require_no_graph_retained_state(unexpected_graph_probe_state)
    checks, results = _foundation_parent_checks_for_children(
        authority, runner, commands, expected_parent, (42, 42)
    )
    runner.finish(
        True,
        [],
        {
            "commands": [list(command) for command in commands],
            "test_results": results,
            "foundation_parent_checks": checks,
            "dylib_empty": _require_host_dylib_sentinel(authority),
        },
    )


def _run_host_foundation_bin_compile(
    authority: Authority, metadata: DarwinMetadataRecorder
) -> None:
    phase = "host-validation-foundation-bin-compile"
    paths = _host_validation_paths(authority)
    commands = _host_exact_commands(authority, phase)
    expected_before = _read_prior_foundation_state(
        authority, "host-validation-foundation-test-compile", "foundation_parent_after_test"
    )
    foundation_xattr_capability = _foundation_traversal_xattr_capability(
        authority, paths["foundation"]
    )
    bin_build_xattr_capability = _foundation_traversal_xattr_capability(
        authority, paths["bin-build"]
    )
    before = _foundation_parent_state(authority, paths["foundation"])
    if before != expected_before:
        fail("foundation parent changed before bin-build creation")
    metadata.capture("pre-foundation-bin-root-create")
    _mkdir_new(
        paths["bin-build"],
        0o700,
        xattr_capability=bin_build_xattr_capability,
        parent_traversal_capability=foundation_xattr_capability,
    )
    metadata.capture("post-foundation-bin-root-create")
    parent_fd = _open_directory_nofollow(paths["foundation"])
    try:
        parent_after_create = _foundation_parent_state_fd(
            authority,
            parent_fd,
            paths["foundation"],
            foundation_xattr_capability,
        )
        before_parent_fields = {
            key: value for key, value in before.items() if key != "entries"
        }
        created_parent_fields = {
            key: value
            for key, value in parent_after_create.items()
            if key != "entries"
        }
        before_entries = {item["name"]: item for item in before["entries"]}
        created_entries = {
            item["name"]: item for item in parent_after_create["entries"]
        }
        if (
            before_parent_fields != created_parent_fields
            or tuple(created_entries) != ("bin-build", "deps", "test-build")
            or {name: created_entries[name] for name in ("deps", "test-build")}
            != before_entries
            or created_entries["bin-build"]["mode"] != "0700"
        ):
            fail("foundation parent did not gain exactly bin-build")
        metadata.capture("pre-foundation-parent-seal")
        os.fchmod(parent_fd, 0o500)
        os.fsync(parent_fd)
        after_create = _foundation_parent_state_fd(
            authority,
            parent_fd,
            paths["foundation"],
            foundation_xattr_capability,
        )
        metadata.capture("post-foundation-parent-seal")
    finally:
        os.close(parent_fd)
    if (
        parent_after_create["mode"] != "0700"
        or after_create["mode"] != "0500"
        or {
            key: value
            for key, value in parent_after_create.items()
            if key != "mode"
        }
        != {key: value for key, value in after_create.items() if key != "mode"}
    ):
        fail("foundation parent did not seal before bin compile")
    output_fd = _open_directory_nofollow(paths["bin-build"])
    try:
        pre_probe = _foundation_output_root_state_fd(
            authority,
            output_fd,
            paths["bin-build"],
            "pre_probe",
            bin_build_xattr_capability,
        )
        if pre_probe["mode"] != "0700" or os.listdir(output_fd):
            fail("foundation binary output root is not initially empty")
        runner = PhaseRunner(authority, phase, metadata)
        runner.set_policy(_host_validation_policy(authority, phase, runner, commands))
        unexpected_graph_probe_state = runner.run_probe(
            _phase_denied_reads(authority, phase)
        )
        _require_no_graph_retained_state(unexpected_graph_probe_state)
        post_probe = _foundation_output_root_state_fd(
            authority,
            output_fd,
            paths["bin-build"],
            "post_probe",
            bin_build_xattr_capability,
        )
        if (
            {**pre_probe, "stage": "post_probe"} != post_probe
            or os.listdir(output_fd)
        ):
            fail("foundation policy probe changed the binary output root")
        pre = _foundation_output_root_state_fd(
            authority,
            output_fd,
            paths["bin-build"],
            "pre_child",
            bin_build_xattr_capability,
        )
        if {**post_probe, "stage": "pre_child"} != pre:
            fail("foundation binary output root changed before compile")
        _verify_foundation_repository_reads(phase)
        result, unexpected_graph_child_state = runner.run_child(
            commands[0],
            _host_validation_environment(authority, runner, commands[0]),
            authority.root_a + "/payload",
            deadline=1_800,
            allowed_tree_deltas=frozenset({"foundation-bin"}),
        )
        _require_no_graph_retained_state(unexpected_graph_child_state)
        if not result.succeeded or result.stderr:
            fail("foundation binary compile did not exit zero with empty stderr")
        post = _foundation_output_root_state_fd(
            authority,
            output_fd,
            paths["bin-build"],
            "post_child",
            bin_build_xattr_capability,
        )
        if {**pre, "stage": "post_child"} != post:
            fail("foundation binary compiler changed output-root metadata")
        metadata.capture("pre-foundation-bin-output-seal")
        output, bin_identity = _seal_foundation_executable(
            authority,
            paths["bin-build"],
            paths["bin"],
            output_fd,
            bin_build_xattr_capability,
        )
        metadata.capture("post-foundation-bin-output-seal")
        final_output = _foundation_output_root_state_fd(
            authority,
            output_fd,
            paths["bin-build"],
            "final",
            bin_build_xattr_capability,
        )
    finally:
        os.close(output_fd)
    if (
        {key: value for key, value in post.items() if key not in ("stage", "mode")}
        != {key: value for key, value in final_output.items() if key not in ("stage", "mode")}
        or pre["mode"] != "0700"
        or post["mode"] != "0700"
        or final_output["mode"] != "0500"
    ):
        fail("foundation binary output-root seal transition is not exact")
    final_parent = _foundation_parent_state(authority, paths["foundation"])
    if final_parent["mode"] != "0500" or tuple(
        (item["name"], item["mode"]) for item in final_parent["entries"]
    ) != (("bin-build", "0500"), ("deps", "0500"), ("test-build", "0500")):
        fail("foundation parent final state is not exact")
    _write_foundation_tree_evidence(runner.evidence, bin_identity)
    runner.finish(
        True,
        [],
        {
            "commands": [list(commands[0])],
            "output": output,
            "output_root_states": [pre, post, final_output],
            "foundation_parent_states": [
                {"stage": "before_bin_create", **before},
                {"stage": "after_bin_create", **after_create},
                {"stage": "final", **final_parent},
            ],
            "dylib_empty": _require_host_dylib_sentinel(authority),
        },
    )


def _run_host_foundation_bin_run(
    authority: Authority, metadata: DarwinMetadataRecorder
) -> None:
    phase = "host-validation-foundation-bin-run"
    commands = _host_exact_commands(authority, phase)
    prior = _read_valid_phase_result(authority, "host-validation-foundation-bin-compile")
    states = prior.get("observations", {}).get("foundation_parent_states")
    if not isinstance(states, list) or len(states) != 3 or not isinstance(states[-1], dict):
        fail("foundation bin-compile result lacks its final parent state")
    expected_parent = {key: value for key, value in states[-1].items() if key != "stage"}
    runner = PhaseRunner(authority, phase, metadata)
    runner.set_policy(_host_validation_policy(authority, phase, runner, commands))
    unexpected_graph_probe_state = runner.run_probe(
        _phase_denied_reads(authority, phase)
    )
    _require_no_graph_retained_state(unexpected_graph_probe_state)
    checks, results = _foundation_parent_checks_for_children(
        authority, runner, commands, expected_parent, (None,)
    )
    expected_output = (
        b"foundation_valid=true\n"
        b"provider_free=true\n"
        b"runtime_implemented=false\n"
        b"c2b2a_acceptance_proven=false\n"
        b"flagship_goal_complete=false\n"
    )
    if runner.stdout_frames != [expected_output] or runner.stderr_frames != [b""]:
        fail("foundation binary output differs from its exact five-line contract")
    runner.finish(
        True,
        [],
        {
            "commands": [list(commands[0])],
            "command_results": results,
            "foundation_parent_checks": checks,
            "dylib_empty": _require_host_dylib_sentinel(authority),
        },
    )


def _run_host_lints(
    authority: Authority, metadata: DarwinMetadataRecorder
) -> None:
    phase = "host-validation-lints"
    paths = _host_validation_paths(authority)
    host_xattr_capability = _generated_xattr_capability(
        authority, paths["root"], "owner-root"
    )
    lints_xattr_capability = _generated_xattr_capability(
        authority, paths["lints"], "host-sealed-tree"
    )
    metadata.capture("pre-host-lints-root-create")
    _mkdir_new(
        paths["lints"],
        0o700,
        xattr_capability=lints_xattr_capability,
        parent_traversal_capability=host_xattr_capability,
    )
    metadata.capture("post-host-lints-root-create")
    commands = _host_exact_commands(authority, phase)
    prior = _read_valid_phase_result(authority, "host-validation-foundation-bin-compile")
    states = prior.get("observations", {}).get("foundation_parent_states")
    if not isinstance(states, list) or len(states) != 3 or not isinstance(states[-1], dict):
        fail("foundation bin-compile result lacks its final parent state")
    expected_parent = {key: value for key, value in states[-1].items() if key != "stage"}
    repository_before = _validate_final_repository_delta(authority)
    runner = PhaseRunner(authority, phase, metadata)
    runner.set_policy(_host_validation_policy(authority, phase, runner, commands))
    unexpected_graph_probe_state = runner.run_probe(
        _phase_denied_reads(authority, phase)
    )
    _require_no_graph_retained_state(unexpected_graph_probe_state)
    checks, results = _foundation_parent_checks_for_children(
        authority, runner, commands, expected_parent, (None,) * 8
    )
    repository_after = _validate_final_repository_delta(authority)
    if repository_before.stream != repository_after.stream:
        fail("lint matrix changed the bounded repository candidate")
    metadata.capture("pre-host-lints-seal")
    lint_tree = _seal_host_generated_tree(paths["lints"])
    metadata.capture("post-host-lints-seal")
    metadata.capture("pre-host-ambient-seal")
    _seal_ambient_parents(authority, paths["root"])
    metadata.capture("post-host-ambient-seal")
    runner.finish(
        True,
        [],
        {
            "commands": _root_remapped_commands(commands, authority.root_a),
            "command_results": results,
            "foundation_parent_checks": checks,
            "repository_tree_sha256": repository_after.sha256,
            "sealed_target": lint_tree,
            "dylib_empty": _require_host_dylib_sentinel(authority),
        },
    )


def _completion_required_paths(authority: Authority) -> dict[str, str]:
    required: dict[str, str] = {}
    for path in {
        authority.acquisition_root + "/evidence",
        authority.acquisition_root + "/lock-root/evidence",
        authority.root_a + "/evidence",
        authority.root_b + "/evidence",
    }:
        required[path] = "evidence-parent"
    for phase in PHASES:
        directory = _phase_directory(authority, phase)
        required[directory] = "phase-directory"
        for basename in authority.phase_evidence_leaves[phase]:
            required[directory + "/" + basename] = "evidence-leaf"
    return required


def _evidence_parent_xattr_capability(
    authority: Authority, path: str
) -> XattrTraversalCapability:
    closed = {
        authority.acquisition_root + "/evidence": authority.acquisition_root,
        authority.acquisition_root + "/lock-root/evidence": (
            authority.acquisition_root + "/lock-root"
        ),
        authority.root_a + "/evidence": authority.root_a,
        authority.root_b + "/evidence": authority.root_b,
    }
    owner = closed.get(path)
    if owner is None:
        fail("evidence parent is outside its exact owner table")
    if path != owner + "/evidence":
        fail("evidence parent differs from its exact owner-relative path")
    return _generated_xattr_capability(authority, path, "evidence-parent")


def _completion_entry_inventory(fd: int) -> tuple[int, str]:
    rows: list[bytes] = []
    names = sorted(os.listdir(fd), key=raw_key)
    if len(names) != len(set(names)):
        fail("completion audit observed duplicate directory entries")
    for name in names:
        info = os.stat(name, dir_fd=fd, follow_symlinks=False)
        kind = _filesystem_kind(info)
        if kind == "symlink":
            fail("completion evidence tree contains a symlink")
        rows.append(
            (
                "entry\t"
                + kind
                + "\t"
                + name
                + "\t"
                + str(info.st_dev)
                + "\t"
                + str(info.st_ino)
                + "\n"
            ).encode("utf-8")
        )
    stream = b"".join(rows)
    return len(rows), sha256_bytes(stream)


def _completion_serialized_sidecar(
    authority: Authority, source: str, path: str
) -> bytes:
    parts = source.split(":")
    if len(parts) != 3 or parts[0] != "darwin-carrier":
        fail("completion xattr source is not an exact carrier selector")
    phase, label = parts[1], parts[2]
    if phase == "graph-finalize" or phase not in authority.darwin_metadata_checks:
        fail("completion xattr source names a phase without metadata evidence")
    checks = authority.darwin_metadata_checks[phase]
    accepted_source_carrier = _read_darwin_metadata_carrier(authority, phase)
    entries = accepted_source_carrier[0]
    matches = [
        row
        for check, row in zip(checks, entries, strict=True)
        if check.label == label and check.root == path and row[3] == "full"
    ]
    if len(matches) != 1 or not isinstance(matches[0][8], bytes):
        fail("completion xattr source is not one unique retained full sidecar")
    return matches[0][8]


def _completion_gate_content_index(
    result: Mapping[str, Any],
) -> dict[tuple[str, str], str]:
    observations = result.get("observations")
    if not isinstance(observations, dict):
        fail("pre-runtime result lacks its exact gate observations")
    indexed: dict[tuple[str, str], str] = {}
    for number in range(1, 22):
        gate = f"gate_{number:02d}"
        value = observations.get(gate)
        if (
            not isinstance(value, dict)
            or tuple(value) != ("passed", "evidence")
            or value["passed"] is not True
            or not isinstance(value["evidence"], list)
            or not value["evidence"]
        ):
            fail("pre-runtime gate observation schema is not exact")
        ordered_paths: list[bytes] = []
        for row in value["evidence"]:
            if not isinstance(row, dict) or tuple(row) != ("path", "sha256"):
                fail("pre-runtime gate evidence row schema is not exact")
            path = row["path"]
            digest = row["sha256"]
            if not isinstance(path, str) or not isinstance(digest, str):
                fail("pre-runtime gate evidence row type is not exact")
            canonical_absolute_lexical(path)
            require_sha256(digest)
            ordered_paths.append(raw_key(path))
            key = (gate, path)
            if key in indexed:
                fail("pre-runtime gate evidence repeats a path")
            indexed[key] = digest
        if ordered_paths != sorted(ordered_paths) or len(ordered_paths) != len(
            set(ordered_paths)
        ):
            fail("pre-runtime gate evidence is duplicated or unordered")
    return indexed


def _completion_serialized_metadata(
    authority: Authority,
    results: Mapping[str, Mapping[str, Any]],
    source: str,
    path: str,
    projection: Mapping[str, Any],
) -> None:
    parts = source.split(":")
    if len(parts) != 3 or parts[0] != "phase-result":
        fail("completion metadata source is not an exact result selector")
    phase, observation = parts[1], parts[2]
    if (
        phase == "graph-finalize"
        or phase not in authority.phase_observations
        or (observation, "object") not in authority.phase_observations[phase]
        or phase not in results
    ):
        fail("completion metadata source is outside result authority")
    observations = results[phase].get("observations")
    if not isinstance(observations, dict):
        fail("completion metadata source result has no observations")
    expected = observations.get(observation)
    if not isinstance(expected, dict) or tuple(expected) != tuple(projection):
        fail("serialized completion metadata schema is not exact")
    if expected.get("path") != path or expected != projection:
        fail("completion metadata differs from its serialized result authority")


def _completion_audit_entry(
    authority: Authority,
    item: CompletionAuditObject,
    required: Mapping[str, str],
    phase_results: Mapping[str, Mapping[str, Any]],
    gate_content: Mapping[tuple[str, str], str],
) -> tuple[Any, ...]:
    if required.get(item.path) != item.object_class:
        fail("completion-audit object class/path is outside exact coverage")
    traversal_xattr_capability = _completion_xattr_capability(authority, item)
    object_xattr_capability = _xattr_object_capability(
        authority,
        traversal_xattr_capability,
        item.path,
        root=True,
    )
    info = os.stat(item.path, follow_symlinks=False)
    if item.object_class == "evidence-leaf":
        fd = _open_absolute(item.path, os.O_RDONLY)
    else:
        fd = _open_directory_nofollow(item.path)
    try:
        opened = _assert_generated_fd(fd, authority, object_xattr_capability)
        if not _full_darwin_identity_equal(info, opened):
            fail("completion-audit object identity changed while opened")
        kind = _filesystem_kind(opened)
        if item.object_class == "evidence-leaf":
            if (
                kind != "file"
                or opened.st_nlink != 1
                or stat.S_IMODE(opened.st_mode) != 0o600
            ):
                fail("completion-audit evidence leaf metadata is not exact")
            content_size, content_sha = _file_digest_from_fd(fd)
            entries = 0
            inventory_sha = sha256_bytes(b"")
            content_size_field = str(content_size)
            content_sha_field = content_sha
        else:
            if kind != "directory" or stat.S_IMODE(opened.st_mode) != 0o500:
                fail("completion-audit directory is not in its final sealed state")
            entries, inventory_sha = _completion_entry_inventory(fd)
            content_size_field = "-"
            content_sha_field = "-"
        portable, native = _acl_external_fd(fd)
        if portable or native:
            fail("completion evidence object has an extended ACL")
        metadata_projection = {
            "path": item.path,
            "kind": kind,
            "device": opened.st_dev,
            "inode": opened.st_ino,
            "uid": opened.st_uid,
            "gid": opened.st_gid,
            "mode": _mode_text(opened.st_mode),
            "nlink": opened.st_nlink,
            "flags": opened.st_flags,
            "birthtime_ns": _birthtime_ns(opened),
            "size": opened.st_size,
            "mtime_ns": opened.st_mtime_ns,
            "ctime_ns": opened.st_ctime_ns,
            "acl_portable_hex": portable.hex() if portable else "-",
            "acl_native_hex": native.hex() if native else "-",
        }
        if item.metadata_authority == "serialized":
            _completion_serialized_metadata(
                authority,
                phase_results,
                item.metadata_source,
                item.path,
                metadata_projection,
            )
        sidecar = _canonical_xattr_sidecar_stream(
            authority, item.path, traversal_xattr_capability, fd
        )
        raw_sidecar_stream = sidecar.stream
        parsed_sidecar = c2b2a_parse_xattr_sidecar(raw_sidecar_stream)
        canonical_sidecar_stream = c2b2a_encode_xattr_sidecar(parsed_sidecar)
        canonical_sidecar_rows = canonical_sidecar_stream.count(b"\n")
        canonical_sidecar_bytes = len(canonical_sidecar_stream)
        canonical_sidecar_sha256 = sha256_bytes(canonical_sidecar_stream)
        if (
            canonical_sidecar_stream != raw_sidecar_stream
            or (
                canonical_sidecar_rows,
                canonical_sidecar_bytes,
                canonical_sidecar_sha256,
            )
            != (sidecar.rows, sidecar.bytes, sidecar.sha256)
        ):
            fail("completion sidecar did not reconstruct its canonical source")
        raw_sidecar_stream = b""
        if (
            item.xattr_authority == "serialized"
            and canonical_sidecar_stream
            != _completion_serialized_sidecar(
                authority, item.xattr_source, item.path
            )
        ):
            fail("completion sidecar differs from its serialized pre-runtime authority")
        if item.content_authority == "serialized":
            if item.object_class != "evidence-leaf":
                fail("serialized completion content is not a regular evidence leaf")
            gate = item.content_source.split(":", 1)[1]
            expected_content = gate_content.get((gate, item.path))
            if expected_content is None or expected_content != content_sha_field:
                fail(
                    "completion content differs from its serialized pre-runtime gate authority"
                )
        final_info = _assert_generated_fd(fd, authority, object_xattr_capability)
        linked_final = os.stat(item.path, follow_symlinks=False)
        if (
            not _full_darwin_identity_equal(opened, final_info)
            or not _full_darwin_identity_equal(opened, linked_final)
        ):
            fail("completion-audit object changed during its held-FD epoch")
        if kind == "file":
            final_content_size, final_content_sha = _file_digest_from_fd(fd)
            if (final_content_size, final_content_sha) != (
                content_size,
                content_sha,
            ):
                fail("completion-audit leaf content changed during its held-FD epoch")
        else:
            final_entries, final_inventory_sha = _completion_entry_inventory(fd)
            if (final_entries, final_inventory_sha) != (entries, inventory_sha):
                fail("completion-audit inventory changed during its held-FD epoch")
        empty_sha = sha256_bytes(b"")
        return (
            str(item.sequence),
            item.object_class,
            item.path,
            kind,
            str(opened.st_dev),
            str(opened.st_ino),
            str(opened.st_uid),
            str(opened.st_gid),
            _mode_text(opened.st_mode),
            str(opened.st_nlink),
            str(opened.st_flags),
            str(_birthtime_ns(opened)),
            str(opened.st_size),
            str(opened.st_mtime_ns),
            str(opened.st_ctime_ns),
            str(len(portable)),
            sha256_bytes(portable),
            portable.hex() if portable else "-",
            str(len(native)),
            sha256_bytes(native),
            native.hex() if native else "-",
            str(entries),
            inventory_sha if kind == "directory" else empty_sha,
            content_size_field,
            content_sha_field,
            item.metadata_authority,
            item.metadata_source,
            item.content_authority,
            item.content_source,
            item.xattr_authority,
            item.xattr_source,
            str(len(parsed_sidecar)),
            str(canonical_sidecar_rows),
            str(canonical_sidecar_bytes),
            canonical_sidecar_sha256,
            canonical_sidecar_stream,
        )
    finally:
        os.close(fd)


def _run_completion_audit_scan(authority: Authority) -> None:
    global CURRENT_AUTHORITY
    CURRENT_AUTHORITY = authority
    verify_authority(authority)
    _validate_controller_runtime(authority)
    accepted_pre_runtime_carrier = _read_darwin_metadata_carrier(
        authority, "pre-runtime-finalize"
    )
    serialized_marker_rows = accepted_pre_runtime_carrier[1]
    if len(serialized_marker_rows) != 4:
        fail("completion scanner lacks the exact four-row marker authority")
    completion_marker_rows = tuple(serialized_marker_rows)
    accepted_pre_completion_marker_rows = _validate_marker_rows_at_boundary(
        authority,
        "completion-audit-scan",
        "pre-completion-audit-scan",
        completion_marker_rows,
    )
    completion_marker_rows = accepted_pre_completion_marker_rows
    for path, digest in COMPLETION_SCANNER_TRUST_ANCHORS.items():
        verify_file(path, digest)
    for path in (COMPLETION_AUDIT, COMPLETION_AUDIT_DIGEST, COMPLETION_AUDIT_REVIEW):
        if os.path.lexists(path):
            fail("completion-audit destination or review already exists")
    evidence_parent_devices = {
        _require_directory(
            path,
            0o500,
            _evidence_parent_xattr_capability(authority, path),
        )[0]
        for path in (
            authority.acquisition_root + "/evidence",
            authority.acquisition_root + "/lock-root/evidence",
            authority.root_a + "/evidence",
            authority.root_b + "/evidence",
        )
    }
    if len(evidence_parent_devices) != 1:
        fail("final evidence parents are not on one device")
    required = _completion_required_paths(authority)
    if {
        item.path: item.object_class for item in authority.completion_audit_objects
    } != required:
        fail("completion-audit applicability is not the exact final evidence closure")
    phase_results: dict[str, Mapping[str, Any]] = {}
    phase_acceptances: dict[str, PhaseEvidenceAcceptance] = {}
    for phase in PHASES:
        accepted_phase = _validate_phase_evidence_bundle(
            authority, phase, phase_acceptances
        )
        phase_acceptances[phase] = accepted_phase
        result = accepted_phase.result
        if result is not None:
            phase_results[phase] = result
    _validate_retained_state_handoffs(
        authority,
        phase_acceptances,
        (0, 1, 2),
        require_live_graph_state=True,
    )
    pre_runtime_result = phase_results.get("pre-runtime-finalize")
    if pre_runtime_result is None:
        fail("completion scanner lacks the successful pre-runtime result")
    gate_content = _completion_gate_content_index(pre_runtime_result)
    gate_paths = {path for _gate, path in gate_content}
    pre_runtime_directory = _phase_directory(authority, "pre-runtime-finalize")
    prior_leaf_paths = {
        _phase_directory(authority, phase) + "/" + basename
        for phase in PHASES
        if phase != "pre-runtime-finalize"
        for basename in authority.phase_evidence_leaves[phase]
    }
    if not prior_leaf_paths.issubset(gate_paths) or not gate_paths.issubset(
        prior_leaf_paths
    ):
        fail("pre-runtime gate content authority is not the exact prior-leaf closure")
    for item in authority.completion_audit_objects:
        is_pre_runtime_object = item.path == pre_runtime_directory or _path_is_beneath(
            item.path, pre_runtime_directory
        )
        if item.path in prior_leaf_paths:
            if item.content_authority != "serialized":
                fail("persisted prior-leaf content is misclassified as containment")
        elif item.content_authority != "containment":
            fail("unserialized directory or pre-runtime content claims temporal authority")
        if is_pre_runtime_object:
            if item.xattr_authority != "containment":
                fail("pre-runtime self-xattr claims impossible retained authority")
        elif item.xattr_authority != "serialized":
            fail("retained pre-runtime xattr sidecar is misclassified as containment")
    entries = tuple(
        _completion_audit_entry(
            authority,
            item,
            required,
            phase_results,
            gate_content,
        )
        for item in authority.completion_audit_objects
    )
    try:
        raw_stream = c2b2a_encode_completion_audit_tsv(entries)
        parsed_entries = c2b2a_parse_completion_audit_tsv(raw_stream)
        canonical_stream = c2b2a_encode_completion_audit_tsv(parsed_entries)
        if canonical_stream != raw_stream or parsed_entries != entries:
            fail("completion audit TSV did not round-trip canonically")
        raw_stream = b""
        raw_digest = c2b2a_encode_completion_audit_digest(canonical_stream)
        digest_identity = c2b2a_parse_completion_audit_digest(
            raw_digest, canonical_stream
        )
        canonical_digest = c2b2a_encode_completion_audit_digest(
            canonical_stream
        )
        if canonical_digest != raw_digest:
            fail("completion audit digest did not reconstruct canonically")
        raw_digest = b""
        if digest_identity != (
            canonical_stream.count(b"\n"),
            len(canonical_stream),
            sha256_bytes(canonical_stream),
        ):
            fail("completion audit digest parser returned a changed identity")
    except ValueError as exc:
        raise ControllerError("cannot construct canonical completion audit TSV") from exc
    verify_authority(authority)
    for path, expected_digest in COMPLETION_SCANNER_TRUST_ANCHORS.items():
        verify_file(path, expected_digest)
    accepted_post_completion_marker_rows = _validate_marker_rows_at_boundary(
        authority,
        "completion-audit-scan",
        "post-completion-audit-scan",
        completion_marker_rows,
    )
    completion_marker_rows = accepted_post_completion_marker_rows
    if tuple(completion_marker_rows) != serialized_marker_rows:
        fail("completion scanner changed the serialized Cargo marker authority")
    canonical_tool_tree(authority)
    final_phase_results: dict[str, Mapping[str, Any]] = {}
    final_phase_acceptances: dict[str, PhaseEvidenceAcceptance] = {}
    for phase in PHASES:
        final_accepted_phase = _validate_phase_evidence_bundle(
            authority, phase, final_phase_acceptances
        )
        final_phase_acceptances[phase] = final_accepted_phase
        final_result = final_accepted_phase.result
        if final_result is not None:
            final_phase_results[phase] = final_result
    _validate_retained_state_handoffs(
        authority,
        final_phase_acceptances,
        (0, 1, 2),
        require_live_graph_state=True,
    )
    if final_phase_results != phase_results:
        fail("phase result authority changed before final completion scan")
    final_pre_runtime_result = final_phase_results.get("pre-runtime-finalize")
    if final_pre_runtime_result is None:
        fail("final completion scan lost the pre-runtime result authority")
    final_gate_content = _completion_gate_content_index(final_pre_runtime_result)
    if final_gate_content != gate_content:
        fail("pre-runtime gate authority changed before final completion scan")
    final_entries = tuple(
        _completion_audit_entry(
            authority,
            item,
            required,
            final_phase_results,
            final_gate_content,
        )
        for item in authority.completion_audit_objects
    )
    if final_entries != entries:
        fail("completion-audit closure changed before stdout publication")
    try:
        final_stream = c2b2a_encode_completion_audit_tsv(final_entries)
    except ValueError as exc:
        raise ControllerError(
            "cannot reconstruct final completion-audit closure"
        ) from exc
    if final_stream != canonical_stream:
        fail("completion-audit bytes changed before stdout publication")
    _write_all(1, final_stream)


def _target_debug_absence_observation(
    authority: Authority,
    root: str,
    root_capability: XattrTraversalCapability,
    target_capability: XattrTraversalCapability | None,
) -> dict[str, Any]:
    root_object_capability = _xattr_object_capability(
        authority, root_capability, root, root=True
    )
    root_fd = _open_directory_nofollow(root)
    try:
        root_before = _validate_xattr_object_fd(
            root_fd,
            authority,
            root_object_capability,
            expected_uid=(
                authority.darwin_paths[root].uid
                if root in authority.darwin_paths
                else os.getuid()
            ),
            expected_gid=(
                authority.darwin_paths[root].gid
                if root in authority.darwin_paths
                else os.getgid()
            ),
        )
        root_names = tuple(sorted(os.listdir(root_fd), key=raw_key))
        root_inventory = _completion_entry_inventory(root_fd)
        target_present = "target" in root_names
        target_identity: dict[str, Any] | None = None
        if target_present:
            target_path = root + "/target"
            if target_capability is None:
                fail("unclassified target exists at the direct gate")
            target_object_capability = _xattr_object_capability(
                authority,
                target_capability,
                target_path,
                root=target_path == target_capability.root,
            )
            target_lstat = os.stat(
                "target", dir_fd=root_fd, follow_symlinks=False
            )
            target_fd = os.open(
                "target",
                os.O_RDONLY
                | os.O_DIRECTORY
                | os.O_CLOEXEC
                | getattr(os, "O_NOFOLLOW", 0),
                dir_fd=root_fd,
            )
            try:
                target_before = _validate_xattr_object_fd(
                    target_fd,
                    authority,
                    target_object_capability,
                    expected_uid=os.getuid(),
                    expected_gid=os.getgid(),
                )
                if not _full_identity_equal(target_lstat, target_before):
                    fail("direct-gate target changed while opened no-follow")
                target_names = tuple(sorted(os.listdir(target_fd), key=raw_key))
                target_inventory = _completion_entry_inventory(target_fd)
                try:
                    os.stat("debug", dir_fd=target_fd, follow_symlinks=False)
                except FileNotFoundError:
                    pass
                else:
                    fail("pre-runtime direct gate observed forbidden target/debug")
                target_after = _validate_xattr_object_fd(
                    target_fd,
                    authority,
                    target_object_capability,
                    expected_uid=os.getuid(),
                    expected_gid=os.getgid(),
                )
                try:
                    os.stat("debug", dir_fd=target_fd, follow_symlinks=False)
                except FileNotFoundError:
                    pass
                else:
                    fail("target/debug appeared during descriptor-bound absence check")
                if (
                    not _full_identity_equal(target_before, target_after)
                    or target_names
                    != tuple(sorted(os.listdir(target_fd), key=raw_key))
                    or target_inventory != _completion_entry_inventory(target_fd)
                ):
                    fail("target directory changed during debug absence check")
                target_identity = {
                    "device": target_after.st_dev,
                    "inode": target_after.st_ino,
                    "uid": target_after.st_uid,
                    "gid": target_after.st_gid,
                    "mode": _mode_text(target_after.st_mode),
                    "flags": getattr(target_after, "st_flags", 0),
                    "entries": target_inventory[0],
                    "inventory_sha256": target_inventory[1],
                }
            finally:
                os.close(target_fd)
        else:
            try:
                os.stat("target", dir_fd=root_fd, follow_symlinks=False)
            except FileNotFoundError:
                pass
            else:
                fail("target appeared during descriptor-bound absence check")
        root_after = _validate_xattr_object_fd(
            root_fd,
            authority,
            root_object_capability,
            expected_uid=(
                authority.darwin_paths[root].uid
                if root in authority.darwin_paths
                else os.getuid()
            ),
            expected_gid=(
                authority.darwin_paths[root].gid
                if root in authority.darwin_paths
                else os.getgid()
            ),
        )
        linked_after = os.stat(root, follow_symlinks=False)
        if (
            not _full_identity_equal(root_before, root_after)
            or not _full_identity_equal(root_before, linked_after)
            or root_names != tuple(sorted(os.listdir(root_fd), key=raw_key))
            or root_inventory != _completion_entry_inventory(root_fd)
        ):
            fail("direct-gate root changed during target/debug absence check")
        return {
            "root": root,
            "root_device": root_after.st_dev,
            "root_inode": root_after.st_ino,
            "root_entries": root_inventory[0],
            "root_inventory_sha256": root_inventory[1],
            "target_present": target_present,
            "target": target_identity,
            "debug_absent": True,
        }
    finally:
        os.close(root_fd)


def _pre_runtime_gate_21_direct_check(authority: Authority) -> Mapping[str, Any]:
    lock_root = authority.acquisition_root + "/lock-root"
    roots = (
        (
            REPOSITORY,
            _preflight_xattr_capability(
                authority, REPOSITORY, "darwin-metadata-check"
            ),
            _preflight_xattr_capability(
                authority, REPOSITORY + "/target", "darwin-metadata-check"
            ),
        ),
        (
            PAYLOAD,
            _preflight_xattr_capability(authority, PAYLOAD, "payload-tree"),
            None,
        ),
        (
            authority.acquisition_root,
            _generated_xattr_capability(
                authority, authority.acquisition_root, "owner-root"
            ),
            _generated_xattr_capability(
                authority,
                authority.acquisition_root + "/target",
                "acquisition-owner-tree",
            ),
        ),
        (
            lock_root,
            _generated_xattr_capability(authority, lock_root, "owner-root"),
            _generated_xattr_capability(authority, lock_root, "owner-root"),
        ),
        (
            authority.root_a,
            _generated_xattr_capability(authority, authority.root_a, "owner-root"),
            _generated_xattr_capability(
                authority, authority.root_a + "/target", "mutable-target-tree"
            ),
        ),
        (
            authority.root_b,
            _generated_xattr_capability(authority, authority.root_b, "owner-root"),
            _generated_xattr_capability(
                authority, authority.root_b + "/target", "mutable-target-tree"
            ),
        ),
    )
    absences = tuple(
        _target_debug_absence_observation(
            authority, root, root_capability, target_capability
        )
        for root, root_capability, target_capability in roots
    )
    acquisition_capability = _generated_xattr_capability(
        authority, authority.acquisition_root, "owner-root"
    )
    acquisition_object_capability = _xattr_object_capability(
        authority,
        acquisition_capability,
        authority.acquisition_root,
        root=True,
    )
    acquisition_fd = _open_directory_nofollow(authority.acquisition_root)
    try:
        acquisition_before = _assert_generated_fd(
            acquisition_fd,
            authority,
            acquisition_object_capability,
            expected_uid=os.getuid(),
            expected_gid=os.getgid(),
        )
        reserve = os.fstatvfs(acquisition_fd)
        acquisition_after = _assert_generated_fd(
            acquisition_fd,
            authority,
            acquisition_object_capability,
            expected_uid=os.getuid(),
            expected_gid=os.getgid(),
        )
        if not _full_identity_equal(acquisition_before, acquisition_after):
            fail("disk-reserve authority root changed during fstatvfs")
    finally:
        os.close(acquisition_fd)
    if reserve.f_bavail <= 0 or reserve.f_frsize <= 0:
        fail("pre-runtime direct gate lacks a positive disk reserve")
    repository = _validate_final_repository_delta(authority)
    record = {
        "schema": "c2b2a-pre-runtime-gate-21-direct-v1",
        "absences": list(absences),
        "disk_reserve": {
            "device": acquisition_after.st_dev,
            "inode": acquisition_after.st_ino,
            "fragment_size": reserve.f_frsize,
            "available_blocks": reserve.f_bavail,
            "available_bytes": reserve.f_frsize * reserve.f_bavail,
        },
        "repository": {
            "rows": repository.rows,
            "bytes": repository.bytes,
            "sha256": require_sha256(repository.sha256),
        },
    }
    accepted_record = decode_canonical_json_line(canonical_json_line(record))
    if accepted_record != record:
        fail("pre-runtime direct gate record is not canonically reconstructible")
    return accepted_record


def _validate_pre_runtime_semantic_gate(
    authority: Authority,
    gate: str,
    bindings: Sequence[SemanticGateBinding],
    accepted_phases: Mapping[str, PhaseEvidenceAcceptance],
) -> dict[str, Any]:
    if re.fullmatch(r"gate_(0[1-9]|1[0-9]|2[01])", gate) is None:
        fail("semantic gate selector is not closed")
    number = int(gate[-2:])
    dispatch = _semantic_gate_dispatch_row(gate)
    expected_producer = dispatch[1]
    expected_relation = dispatch[2]
    expected_direct = dispatch[3]
    rows: list[dict[str, Any]] = []
    for binding in bindings:
        if (
            binding.gate != gate
            or binding.producer != expected_producer
            or binding.validator
            != _semantic_evidence_validator(binding.basename)
            or binding.relation != expected_relation
            or binding.direct != expected_direct
        ):
            fail("semantic gate binding differs from its exact dispatcher row")
        accepted_phase = accepted_phases.get(binding.phase)
        digest = (
            accepted_phase.leaf_digests.get(binding.basename)
            if accepted_phase is not None
            else None
        )
        if digest is None:
            fail("semantic gate lacks an accepted phase-leaf digest")
        path = _phase_directory(authority, binding.phase) + "/" + binding.basename
        rows.append({"path": path, "sha256": require_sha256(digest)})
    rows.sort(key=lambda item: raw_key(item["path"]))
    if not rows or len(rows) != len({item["path"] for item in rows}):
        fail("semantic gate evidence rows are empty or duplicated")
    row_paths = {item["path"] for item in rows}
    if number == 21:
        direct_record = _pre_runtime_gate_21_direct_check(authority)
        if (
            tuple(direct_record) != (
                "schema",
                "absences",
                "disk_reserve",
                "repository",
            )
            or direct_record["schema"]
            != "c2b2a-pre-runtime-gate-21-direct-v1"
            or not isinstance(direct_record["absences"], list)
            or len(direct_record["absences"]) != 6
            or not isinstance(direct_record["disk_reserve"], dict)
            or direct_record["disk_reserve"].get("available_bytes", 0) <= 0
            or not isinstance(direct_record["repository"], dict)
        ):
            fail("pre-runtime direct gate did not reconstruct its exact record")
    elif number == 4:
        required_result_paths = {
            _phase_directory(authority, selected_phase) + "/result.json"
            for selected_phase in ("acquisition-fetch", "acquisition-stage")
        }
        if not required_result_paths.issubset(row_paths):
            fail("gate 04 omits its retained-state producer or acceptance")
        _validate_retained_state_handoffs(
            authority,
            accepted_phases,
            (0,),
            require_live_graph_state=False,
        )
    elif number in (9, 10):
        required_result_paths = {
            _phase_directory(authority, selected_phase) + "/result.json"
            for selected_phase in ("lock-derive", "graph-metadata", "archive-seal")
        }
        if not required_result_paths.issubset(row_paths):
            fail("gate 09/10 omits its retained-state handoff chain")
        _validate_retained_state_handoffs(
            authority,
            accepted_phases,
            (1, 2),
            require_live_graph_state=False,
        )
    return {"passed": True, "evidence": rows}


def _run_pre_runtime_finalize(
    authority: Authority, metadata: DarwinMetadataRecorder
) -> None:
    phase = "pre-runtime-finalize"
    started = time.monotonic_ns()
    deadline = started + DEADLINES[phase] * 1_000_000_000
    if os.path.lexists(_phase_directory(authority, phase)):
        fail("pre-runtime-finalize path exists before entry scan")
    acquisition_evidence = authority.acquisition_root + "/evidence"
    acquisition_evidence_xattr_capability = _evidence_parent_xattr_capability(
        authority, acquisition_evidence
    )
    _require_directory(
        acquisition_evidence, 0o700, acquisition_evidence_xattr_capability
    )
    for path in (
        authority.acquisition_root + "/lock-root/evidence",
        authority.root_a + "/evidence",
        authority.root_b + "/evidence",
    ):
        _require_directory(
            path, 0o500, _evidence_parent_xattr_capability(authority, path)
        )
    metadata.capture("pre-runtime-entry")
    verify_authority(authority)
    accepted_phases: dict[str, PhaseEvidenceAcceptance] = {}
    for earlier in PHASES[: PHASES.index(phase)]:
        if time.monotonic_ns() > deadline:
            fail("pre-runtime-finalize exceeded its self-deadline")
        accepted_phase = _validate_phase_evidence_bundle(
            authority, earlier, accepted_phases
        )
        accepted_phases[earlier] = accepted_phase
        if earlier == "graph-finalize":
            if accepted_phase.result is not None:
                fail("graph-finalize completion unexpectedly returned a result")
        elif not isinstance(accepted_phase.result, Mapping):
            fail("ordinary earlier phase completion did not return its result")
    _validate_retained_state_handoffs(
        authority,
        accepted_phases,
        (0, 1, 2),
        require_live_graph_state=True,
    )
    payload_a = canonical_payload_tree(authority.root_a + "/payload", sealed=True)
    payload_b = canonical_payload_tree(authority.root_b + "/payload", sealed=True)
    source_a = canonical_source_tree(authority.root_a + "/cargo-source")
    source_b = canonical_source_tree(authority.root_b + "/cargo-source")
    if payload_a.stream != payload_b.stream or source_a.stream != source_b.stream:
        fail("pre-runtime A/B payload or source identity differs")
    bundle_a = accepted_phases["artifact-audit-A"].leaves[
        "executable-bundle-v1.tsv"
    ]
    bundle_b = accepted_phases["artifact-audit-B"].leaves[
        "executable-bundle-v1.tsv"
    ]
    if bundle_a != bundle_b:
        fail("pre-runtime A/B executable bundles differ")
    metadata.capture("post-prior-evidence-scan")
    gates: dict[str, Any] = {}
    for index in range(1, 22):
        gate = f"gate_{index:02d}"
        bindings = tuple(
            binding
            for binding in authority.semantic_gate_bindings
            if binding.gate == gate
        )
        gates[gate] = _validate_pre_runtime_semantic_gate(
            authority, gate, bindings, accepted_phases
        )
    metadata.capture("pre-evidence-directory")
    evidence = Evidence(authority, phase)
    metadata.capture("post-evidence-directory")
    metadata.capture("pre-carrier")
    checks = metadata.write_carrier(evidence)
    observations = {**gates, "darwin_metadata_checks": checks}
    for earlier in PHASES[: PHASES.index(phase)]:
        _revalidate_phase_evidence_acceptance(
            authority, accepted_phases[earlier]
        )
    final_payload_a = canonical_payload_tree(
        authority.root_a + "/payload", sealed=True
    )
    final_payload_b = canonical_payload_tree(
        authority.root_b + "/payload", sealed=True
    )
    final_source_a = canonical_source_tree(authority.root_a + "/cargo-source")
    final_source_b = canonical_source_tree(authority.root_b + "/cargo-source")
    if (
        final_payload_a.stream != payload_a.stream
        or final_payload_b.stream != payload_b.stream
        or final_source_a.stream != source_a.stream
        or final_source_b.stream != source_b.stream
        or accepted_phases["artifact-audit-A"].leaves[
            "executable-bundle-v1.tsv"
        ]
        != bundle_a
        or accepted_phases["artifact-audit-B"].leaves[
            "executable-bundle-v1.tsv"
        ]
        != bundle_b
    ):
        fail("accepted live authority changed before pre-runtime result seal")
    evidence.write_json(
        "result.json",
        {
            "schema": "c2b2a-phase-result-v1",
            "phase": phase,
            "valid": True,
            "failures": [],
            "observations": _ordered_phase_observations(authority, phase, observations),
        },
    )
    evidence.seal()
    _require_directory(
        acquisition_evidence, 0o500, acquisition_evidence_xattr_capability
    )
    accepted_marker_rows = _validate_marker_rows_at_boundary(
        authority, phase, "post-phase-seal", metadata.marker_rows
    )
    metadata.marker_rows = accepted_marker_rows
    if time.monotonic_ns() > deadline:
        fail("pre-runtime-finalize exceeded its self-deadline")


def _validate_controller_runtime(authority: Authority) -> None:
    if os.getuid() != 502:
        fail("invoking uid is not the preflight-required 502")
    if sys.executable != authority.tools["python"].path:
        fail("controller interpreter differs from the sealed Python")
    if os.path.realpath(sys.argv[0]) != CONTROLLER:
        fail("controller script path is not exact")
    if os.path.realpath(EMPTY_HOME) != EMPTY_CWD:
        fail("logical /var/empty spelling does not resolve to the frozen physical cwd")
    empty = os.stat(EMPTY_CWD, follow_symlinks=False)
    logical_empty = os.stat(EMPTY_HOME, follow_symlinks=True)
    if (
        not stat.S_ISDIR(empty.st_mode)
        or empty.st_uid != 0
        or empty.st_mode & 0o022
        or os.access(EMPTY_CWD, os.W_OK, effective_ids=True)
        or not _same_identity(empty, logical_empty)
    ):
        fail("/var/empty is not an exact non-writable root-owned directory")
    required_system = {ENV_EXE, SANDBOX_EXE, DEV_NULL, EMPTY_CWD}
    if not required_system.issubset({item.path for item in authority.system_inputs}):
        fail("fixed system entry/runtime paths are absent from system authority")


def run_phase(phase: str, authority: Authority) -> None:
    global CURRENT_AUTHORITY
    CURRENT_AUTHORITY = authority
    verify_authority(authority)
    _validate_controller_runtime(authority)
    accepted_prior = _check_phase_schedule(authority, phase)
    if phase in RETAINED_STATE_CONSUMER_PHASES:
        (
            retained_state_acceptance,
            retained_state_entry_identity,
        ) = _accept_retained_state_at_phase_entry(
            authority, phase, accepted_prior
        )
    else:
        retained_state_acceptance = None
        retained_state_entry_identity = None
    marker_rows = _load_phase_marker_rows(authority, phase)
    metadata: DarwinMetadataRecorder | None
    if phase == "graph-finalize":
        metadata = None
    else:
        metadata = DarwinMetadataRecorder(authority, phase, marker_rows)
        metadata.capture("phase-entry")
    if phase == "acquisition-setup":
        if metadata is None:
            fail("acquisition setup lacks its dispatcher-owned metadata recorder")
        _setup_acquisition(authority, metadata)
    elif phase == "acquisition-fetch":
        if metadata is None:
            fail("acquisition fetch lacks its dispatcher-owned metadata recorder")
        _run_acquisition_fetch(authority, metadata)
    elif phase in (
        "acquisition-stage",
        "lock-payload",
        "lock-source",
        "archive-seal",
        "qualification-A-payload",
        "qualification-A-source",
        "qualification-B-payload",
        "qualification-B-source",
    ):
        if phase == "lock-payload":
            _verify_candidate(authority, published=False)
        if phase in ("qualification-A-payload", "qualification-B-payload"):
            _verify_candidate(authority, published=True)
        if metadata is None:
            fail("provision phase lacks its dispatcher-owned metadata recorder")
        _run_provision_phase(
            authority,
            phase,
            metadata,
            retained_state_acceptance,
            retained_state_entry_identity,
        )
    elif phase in ("lock-derive", "graph-metadata"):
        if metadata is None:
            fail("metadata phase lacks its dispatcher-owned metadata recorder")
        _run_metadata_phase(
            authority,
            phase,
            metadata,
            retained_state_acceptance,
            retained_state_entry_identity,
        )
    elif phase == "graph-finalize":
        if metadata is not None:
            fail("graph-finalize unexpectedly owns an ordinary metadata recorder")
        _run_graph_finalize(authority, marker_rows)
    elif phase in (
        "qualification-A-supervisor",
        "qualification-A-collector",
        "qualification-B-supervisor",
        "qualification-B-collector",
    ):
        if metadata is None:
            fail("qualification phase lacks its dispatcher-owned metadata recorder")
        _run_qualification_build(authority, phase, metadata)
    elif phase in ("probe-build-A", "probe-build-B"):
        if metadata is None:
            fail("probe phase lacks its dispatcher-owned metadata recorder")
        _run_probe_build(authority, phase, metadata)
    elif phase == "source-audit":
        if metadata is None:
            fail("source audit lacks its dispatcher-owned metadata recorder")
        _run_source_audit(authority, metadata)
    elif phase in ("artifact-audit-A", "artifact-audit-B"):
        if metadata is None:
            fail("artifact audit lacks its dispatcher-owned metadata recorder")
        _run_artifact_audit(authority, phase, metadata)
    elif phase == "host-validation-payload-tests":
        if metadata is None:
            fail("host payload tests lack their dispatcher-owned metadata recorder")
        _run_host_payload_tests(authority, metadata)
    elif phase == "host-validation-foundation-test-compile":
        if metadata is None:
            fail("host foundation compile lacks its dispatcher-owned metadata recorder")
        _run_host_foundation_test_compile(authority, metadata)
    elif phase == "host-validation-foundation-test-run":
        if metadata is None:
            fail("host foundation run lacks its dispatcher-owned metadata recorder")
        _run_host_foundation_test_run(authority, metadata)
    elif phase == "host-validation-foundation-bin-compile":
        if metadata is None:
            fail("host foundation bin compile lacks its dispatcher-owned metadata recorder")
        _run_host_foundation_bin_compile(authority, metadata)
    elif phase == "host-validation-foundation-bin-run":
        if metadata is None:
            fail("host foundation bin run lacks its dispatcher-owned metadata recorder")
        _run_host_foundation_bin_run(authority, metadata)
    elif phase == "host-validation-lints":
        if metadata is None:
            fail("host lints lack their dispatcher-owned metadata recorder")
        _run_host_lints(authority, metadata)
    elif phase == "pre-runtime-finalize":
        if metadata is None:
            fail("pre-runtime finalize lacks its dispatcher-owned metadata recorder")
        _run_pre_runtime_finalize(authority, metadata)
    else:
        fail("closed phase has no dispatcher entry")
    # Re-establish both source-script and complete executable/runtime closure
    # identity at the last trusted controller boundary of every phase.
    verify_authority(authority)
    canonical_tool_tree(authority)


def main(argv: Sequence[str]) -> int:
    if not argv:
        fail("missing controller mode")
    mode = argv[0]
    if mode not in PHASES + INTERNAL_MODES:
        fail("unknown controller mode")
    verify_initial_process(mode)
    if mode == "policy-probe":
        return run_policy_probe_process(argv[1:])
    authority = parse_authority(argv[1:])
    if mode == "completion-audit-scan":
        _run_completion_audit_scan(authority)
        return 0
    run_phase(mode, authority)
    _write_all(1, b"controller_valid=true\n")
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main(sys.argv[1:]))
    except ControllerError as exc:
        # Diagnostics are deliberately class-only. Paths, environments, tool
        # output, and other potentially sensitive values belong solely in the
        # sealed evidence leaves.
        _write_all(2, ("controller_error=" + type(exc).__name__ + "\n").encode("ascii"))
        raise SystemExit(2)
